1	/**
2	 * The Agent Client Protocol (ACP) messages Nexus accepts and sends: a SUBSET of ACP version 1, plus Nexus's own
3	 * extension method and `_meta` members. `AcpAdapterDocument` is the published contract
4	 * (docs/protocol/acp-adapter-v1.schema.json, generated by cli/scripts/gen_acp_schema.mjs); a change to a type here
5	 * changes that schema and needs a ledger entry in docs/protocol/ACP_ADAPTER_VERSIONS.json.
6	 *
7	 * Protocol facts are cited as "published specification, <page>" (agentclientprotocol.com protocol pages, checked
8	 * 2026-11-22). Facts that could not be checked are gathered in the one block marked NOT VERIFIED below.
9	 *
10	 * This module is pure: constants and types only, no I/O, no value import from outside cli/src/acp.
11	 */
12	import type { EngineeringOutcome, ExecutionState, TurnReason, VerificationStatus } from "../core/turn.js";
13	import type { ReceiptSection } from "../evidence.js";
14	
15	/** Version of the published schema of this adapter's messages (the ledger key `schema_version`). */
16	export const ACP_ADAPTER_SCHEMA_VERSION = 1;
17	
18	/**
19	 * The ACP protocol version Nexus speaks: an integer major version, currently 1 (published specification,
20	 * initialization). An agent that supports the requested version answers with it; otherwise it answers with the latest
21	 * version it supports. Nexus supports exactly this one, so the answer is always this value.
22	 */
23	export const ACP_PROTOCOL_VERSION = 1;
24	
25	export const JSONRPC_VERSION = "2.0";
26	
27	/**
28	 * JSON-RPC error codes Nexus sends. -32601, -32602, -32000 (authentication required) and -32800 (request cancelled,
29	 * for a request ended by `$/cancel_request`) appear verbatim in the published specification; -32700, -32600 and -32603
30	 * are the standard JSON-RPC codes (specification schema page, read as a summary). -32002 exists in the specification
31	 * for `session/close` and is not used here.
32	 */
33	export const ACP_ERROR = {
34	  PARSE_ERROR: -32700,
35	  INVALID_REQUEST: -32600,
36	  METHOD_NOT_FOUND: -32601,
37	  INVALID_PARAMS: -32602,
38	  INTERNAL_ERROR: -32603,
39	  AUTH_REQUIRED: -32000,
40	  REQUEST_CANCELLED: -32800,
41	} as const;
42	export type AcpErrorCode = (typeof ACP_ERROR)[keyof typeof ACP_ERROR];
43	
44	/**
45	 * Extension names. The specification reserves every method name that starts with an underscore for custom extensions
46	 * and lets `_meta` carry custom data (published specification, extensibility). It RECOMMENDS a reverse-DNS prefix of a
47	 * domain the implementer controls (`_com.example/...`, `com.example/<name>`). Nexus uses the short prefix `nexus`:
48	 * OPEN OWNER DECISION, whether to move to a reverse-DNS prefix before the experimental mark is removed. Every extension
49	 * name is declared here and nowhere else (a test checks each against the two prefixes), so that decision is one edit.
50	 * The `_meta` root keys `traceparent`, `tracestate` and `baggage` are reserved for W3C trace context and never used.
51	 */
52	export const ACP_EXTENSION_METHOD_PREFIX = "_nexus/";
53	export const ACP_META_PREFIX = "nexus/";
54	/** The one extension method: read the receipt of a turn. Reserved and not implemented: `_nexus/verify` (VR-2). */
55	export const ACP_RECEIPT_GET_METHOD = "_nexus/receipt/get";
56	export const ACP_META_VERIFICATION = "nexus/verification";
57	export const ACP_META_POSTURE = "nexus/posture";
58	export const ACP_META_HISTORY = "nexus/history";
59	export const ACP_META_MCP_SERVERS_IGNORED = "nexus/mcp_servers_ignored";
60	export const ACP_META_APPROVAL_DIGEST = "nexus/approval_digest";
61	export const ACP_META_DIFF = "nexus/diff";
62	export const ACP_META_EXPERIMENTAL = "nexus/experimental";
63	export const ACP_META_EXTENSIONS = "nexus/extensions";
64	export const ACP_META_SIDECAR_PROTOCOL = "nexus/sidecar_protocol";
65	
66	/**
67	 * The session update that carries the verification object: `session_info_update` is a session update kind of the
68	 * specification (published specification, prompt-turn / schema) and `_meta` is allowed on session update payloads.
69	 */
70	export const ACP_VERIFICATION_CARRIER = "session_info_update";
71	
72	/** Protocol-level cancellation of one request by id; the cancelled request is answered with -32800 (published specification, schema). */
73	export const ACP_CANCEL_REQUEST_METHOD = "$/cancel_request";
74	
75	/**
76	 * DECLARED DEVIATIONS from the published specification (docs/ACP.md states them):
77	 *
78	 * `ACP_DEVIATION_NO_CLIENT_MCP_SERVERS`: "All Agents MUST support the stdio transport [for MCP servers], while HTTP
79	 * and SSE transports are optional" (session-setup). Nexus v1.3.0 connects no client-supplied MCP server at all: which
80	 * servers load is decided by the operator's allowlist and workspace trust, not by the client. A non-empty `mcpServers`
81	 * is reported in `_meta["nexus/mcp_servers_ignored"]`.
82	 *
83	 * `ACP_DEVIATION_PARTIAL_REPLAY`: on `session/load`, "The Agent MUST replay the entire conversation" (session-setup).
84	 * Nexus replays what the sidecar's `history` event carries (at most 60 entries) and reports `{sent, total}` in
85	 * `_meta["nexus/history"]`.
86	 */
87	export const ACP_DEVIATION_NO_CLIENT_MCP_SERVERS = "client-supplied MCP servers are not connected (stdio included)";
88	export const ACP_DEVIATION_PARTIAL_REPLAY = "session/load replays at most the sidecar's history window, not the entire conversation";
89	
90	/** The only two answers Nexus offers to a permission request. `allow_always` and `reject_always` exist in the specification and are never offered. */
91	export const ACP_ALLOW_ONCE_OPTION_ID = "allow_once";
92	export const ACP_REJECT_ONCE_OPTION_ID = "reject_once";
93	
94	/**
95	 * Limits on untrusted input. The specification sets no message size limit and no batch rule (published
96	 * specification, transports), so every number here, and the refusal of a batch, is Nexus's own choice.
97	 */
98	export const ACP_MAX_LINE_BYTES = 4 * 1024 * 1024;
99	/** Inbound lines over the cap after which the adapter closes the connection. */
100	export const ACP_MAX_OVERSIZED_LINES = 3;
101	/** A sidecar child's line over this marks its session failed. */
102	export const ACP_MAX_CHILD_LINE_BYTES = 16 * 1024 * 1024;
103	export const ACP_MAX_JSON_DEPTH = 64;
104	export const ACP_MAX_TEXT_BLOCK_CHARS = 256_000;
105	export const ACP_MAX_PROMPT_CHARS = 1_000_000;
106	export const ACP_MAX_PROMPT_BLOCKS = 64;
107	export const ACP_MAX_CWD_CHARS = 4_096;
108	export const ACP_MAX_SESSION_ID_CHARS = 128;
109	export const ACP_MAX_URI_CHARS = 2_048;
110	/** The same limit as the sidecar's `MAX_CLIENT_FIELD`, which receives these fields. */
111	export const ACP_MAX_CLIENT_FIELD_CHARS = 100;
112	export const ACP_MAX_MCP_SERVERS_INSPECTED = 32;
113	export const ACP_MAX_SESSIONS = 4;
114	export const ACP_MAX_INFLIGHT_REQUESTS = 32;
115	export const ACP_MAX_PENDING_PERMISSIONS_PER_SESSION = 1;
116	/** Receipts kept per session for `_nexus/receipt/get`. */
117	export const ACP_RECEIPT_STORE_SIZE = 32;
118	/** Settled or abandoned agent-to-client request ids remembered, so a late reply is told apart from an unknown one. */
119	export const ACP_TOMBSTONE_COUNT = 256;
120	/** Seconds without an answer to a permission request before it is denied (`--permission-timeout`). */
121	export const ACP_PERMISSION_TIMEOUT_SECS = 600;
122	/** Longest string id of a request, method name and receipt id accepted. */
123	export const ACP_MAX_REQUEST_ID_CHARS = 256;
124	export const ACP_MAX_METHOD_CHARS = 128;
125	export const ACP_MAX_RECEIPT_ID_CHARS = 256;
126	/** Characters of text in one tool-call content block, and diff blocks in one update. */
127	export const ACP_MAX_TOOL_TEXT_CHARS = 8_000;
128	export const ACP_MAX_DIFF_BLOCKS = 64;
129	/** Characters of a failed turn's detail carried in an error message. */
130	export const ACP_MAX_ERROR_MESSAGE_CHARS = 2_000;
131	
132	// ---------------------------------------------------------------------------------------------------------------------
133	// NOT verified against the published specification as of this slice: see AC1_PLAN.md NV list.
134	// Every value below rests on a summary of the specification's schema page or on Nexus's own choice. Correct them here.
135	// ---------------------------------------------------------------------------------------------------------------------
136	/** `protocolVersion` range accepted in `initialize`: uint16 per a summary of the schema, not its verbatim text. */
137	export const ACP_NV_MAX_PROTOCOL_VERSION = 65_535;
138	/**
139	 * The exact `RequestId` type is known from a summary only (number, string, and null). Nexus accepts a string or an
140	 * integer as a request id and refuses null and a fractional number; for its own agent-to-client requests it sends
141	 * integers only (whether every client accepts string ids is unknown, and integers are accepted by all seen).
142	 */
143	export const ACP_NV_REQUEST_ID_KINDS = ["string", "integer"] as const;
144	/**
145	 * The code answered to any method sent before `initialize`. The specification states the initialize-first rule only for
146	 * session creation; refusing every other method is Nexus's choice, and so is the code.
147	 */
148	export const ACP_NV_NOT_INITIALIZED_CODE = ACP_ERROR.INVALID_REQUEST;
149	/** The code answered to a batch (a top-level array). The specification has no batch rule; the refusal is Nexus's choice. */
150	export const ACP_NV_BATCH_CODE = ACP_ERROR.INVALID_REQUEST;
151	// Also unverified and therefore not used by any code here: the `fs/*` and `terminal/*` method shapes (Nexus never calls
152	// them), every numeric limit above (the specification names none), and whether real clients send a non-empty
153	// `mcpServers` by default.
154	// ---------------------------------------------------------------------------------------------------------------------
155	// End of the NOT VERIFIED block.
156	// ---------------------------------------------------------------------------------------------------------------------
157	
158	/** A JSON-RPC request id: a string or an integer. */
159	export type AcpId = string | number;
160	
161	/** Custom data. Never read for authority: no `_meta` member a client sends changes what a session may do. */
162	export interface AcpMeta {
163	  [key: string]: unknown;
164	}
165	
166	// ---- Client to agent ------------------------------------------------------------------------------------------------
167	
168	export interface AcpImplementationInfo {
169	  name: string;
170	  title?: string | null;
171	  version: string;
172	}
173	
174	/** `clientCapabilities` is accepted and never consulted: Nexus calls no client method (`fs/*`, `terminal/*`) whatever it says. */
175	export interface AcpInitializeParams {
176	  protocolVersion: number;
177	  clientCapabilities?: AcpMeta;
178	  clientInfo?: AcpImplementationInfo | null;
179	  _meta?: AcpMeta;
180	}
181	
182	/**
183	 * `mcpServers` is required by the specification and must be an array; its entries are not connected (see
184	 * ACP_DEVIATION_NO_CLIENT_MCP_SERVERS). `additionalDirectories` is accepted only when empty, and `systemPrompt` is
185	 * refused when present: Nexus supports neither.
186	 */
187	export interface AcpNewSessionParams {
188	  cwd: string;
189	  mcpServers: unknown[];
190	  /** Accepted only when empty or null. */
191	  additionalDirectories?: unknown[] | null;
192	  _meta?: AcpMeta;
193	}
194	
195	export interface AcpLoadSessionParams {
196	  sessionId: string;
197	  cwd: string;
198	  mcpServers: unknown[];
199	  /** Accepted only when empty or null. */
200	  additionalDirectories?: unknown[] | null;
201	  _meta?: AcpMeta;
202	}
203	
204	export interface AcpTextBlock {
205	  type: "text";
206	  text: string;
207	  annotations?: unknown;
208	  _meta?: AcpMeta;
209	}
210	
211	/** Reduced to one reference line of the prompt; Nexus never reads or fetches the URI. */
212	export interface AcpResourceLinkBlock {
213	  type: "resource_link";
214	  uri: string;
215	  name?: string;
216	  title?: string | null;
217	  description?: string | null;
218	  mimeType?: string | null;
219	  size?: number | null;
220	  annotations?: unknown;
221	  _meta?: AcpMeta;
222	}
223	
224	/** The baseline content blocks (published specification, content). `image`, `audio` and `resource` need capabilities Nexus does not declare, and are refused. */
225	export type AcpPromptBlock = AcpTextBlock | AcpResourceLinkBlock;
226	
227	export interface AcpPromptParams {
228	  sessionId: string;
229	  prompt: AcpPromptBlock[];
230	  _meta?: AcpMeta;
231	}
232	
233	export interface AcpCancelParams {
234	  sessionId: string;
235	  _meta?: AcpMeta;
236	}
237	
238	export interface AcpCancelRequestParams {
239	  requestId: AcpId;
240	  _meta?: AcpMeta;
241	}
242	
243	/** Without `receiptId`: the latest receipt of the session. */
244	export interface AcpReceiptGetParams {
245	  sessionId: string;
246	  receiptId?: string;
247	  _meta?: AcpMeta;
248	}
249	
250	export interface AcpPermissionSelected {
251	  outcome: "selected";
252	  optionId: string;
253	  _meta?: AcpMeta;
254	}
255	
256	export interface AcpPermissionCancelled {
257	  outcome: "cancelled";
258	  _meta?: AcpMeta;
259	}
260	
261	export type AcpPermissionOutcome = AcpPermissionSelected | AcpPermissionCancelled;
262	
263	/** Only `selected` with the allow-once option id approves; every other result, well-formed or not, denies. */
264	export interface AcpPermissionResult {
265	  outcome: AcpPermissionOutcome;
266	  _meta?: AcpMeta;
267	}
268	
269	/** The error member of a response a client sends to an agent request. */
270	export interface AcpClientError {
271	  code: number;
272	  message: string;
273	  data?: unknown;
274	}
275	
276	export interface AcpInitializeRequest {
277	  jsonrpc: "2.0";
278	  id: AcpId;
279	  method: "initialize";
280	  params: AcpInitializeParams;
281	}
282	
283	export interface AcpNewSessionRequest {
284	  jsonrpc: "2.0";
285	  id: AcpId;
286	  method: "session/new";
287	  params: AcpNewSessionParams;
288	}
289	
290	export interface AcpLoadSessionRequest {
291	  jsonrpc: "2.0";
292	  id: AcpId;
293	  method: "session/load";
294	  params: AcpLoadSessionParams;
295	}
296	
297	export interface AcpPromptRequest {
298	  jsonrpc: "2.0";
299	  id: AcpId;
300	  method: "session/prompt";
301	  params: AcpPromptParams;
302	}
303	
304	export interface AcpReceiptGetRequest {
305	  jsonrpc: "2.0";
306	  id: AcpId;
307	  method: typeof ACP_RECEIPT_GET_METHOD;
308	  params: AcpReceiptGetParams;
309	}
310	
311	export interface AcpCancelNotification {
312	  jsonrpc: "2.0";
313	  method: "session/cancel";
314	  params: AcpCancelParams;
315	}
316	
317	export interface AcpCancelRequestNotification {
318	  jsonrpc: "2.0";
319	  method: typeof ACP_CANCEL_REQUEST_METHOD;
320	  params: AcpCancelRequestParams;
321	}
322	
323	/** The client's answer to `session/request_permission`; `id` is the integer id of that request. */
324	export interface AcpPermissionResponse {
325	  jsonrpc: "2.0";
326	  id: number;
327	  result: AcpPermissionResult;
328	}
329	
330	/** An error answer to `session/request_permission`: a denial. */
331	export interface AcpPermissionErrorResponse {
332	  jsonrpc: "2.0";
333	  id: number;
334	  error: AcpClientError;
335	}
336	
337	/** Everything a client may send that Nexus acts on. Any other method is answered -32601 (a request) or ignored (a notification). */
338	export type AcpClientMessage =
339	  | AcpInitializeRequest
340	  | AcpNewSessionRequest
341	  | AcpLoadSessionRequest
342	  | AcpPromptRequest
343	  | AcpReceiptGetRequest
344	  | AcpCancelNotification
345	  | AcpCancelRequestNotification
346	  | AcpPermissionResponse
347	  | AcpPermissionErrorResponse;
348	
349	// ---- Agent to client ------------------------------------------------------------------------------------------------
350	
351	export interface AcpAgentCapabilitiesMeta {
352	  [ACP_META_EXPERIMENTAL]: true;
353	  [ACP_META_EXTENSIONS]: string[];
354	  [ACP_META_SIDECAR_PROTOCOL]: number;
355	}
356	
357	/** No `sessionCapabilities`: Nexus offers no session list, resume, fork, close or delete. */
358	export interface AcpAgentCapabilities {
359	  loadSession: true;
360	  promptCapabilities: { image: false; audio: false; embeddedContext: false };
361	  mcpCapabilities: { http: false; sse: false };
362	  _meta: AcpAgentCapabilitiesMeta;
363	}
364	
365	export interface AcpInitializeResult {
366	  protocolVersion: typeof ACP_PROTOCOL_VERSION;
367	  agentInfo: { name: "nexus"; title: "Nexus Code"; version: string };
368	  /** Always empty: Nexus has no authentication method over ACP. */
369	  authMethods: unknown[];
370	  agentCapabilities: AcpAgentCapabilities;
371	}
372	
373	/** The session's posture as the operator's machine set it. Reported, never set, over ACP. */
374	export interface AcpPosture {
375	  mode: "auto" | "review" | "read-only";
376	  sandbox: string;
377	  trusted: boolean;
378	  read_only: boolean;
379	}
380	
381	/** Client-supplied MCP servers that were not connected: how many, and the sanitised names of the first of them. */
382	export interface AcpMcpServersIgnored {
383	  count: number;
384	  names: string[];
385	}
386	
387	/** Conversation entries replayed on load, and how many the session holds. */
388	export interface AcpHistoryExtent {
389	  sent: number;
390	  total: number;
391	}
392	
393	export interface AcpSessionMeta {
394	  [ACP_META_POSTURE]?: AcpPosture;
395	  [ACP_META_MCP_SERVERS_IGNORED]?: AcpMcpServersIgnored;
396	  [ACP_META_HISTORY]?: AcpHistoryExtent;
397	}
398	
399	export interface AcpNewSessionResult {
400	  sessionId: string;
401	  _meta?: AcpSessionMeta;
402	}
403	
404	/** The specification's `session/load` response is an empty object; Nexus's own data is under `_meta`. */
405	export interface AcpLoadSessionResult {
406	  _meta?: AcpSessionMeta;
407	}
408	
409	/** `refusal` exists in the specification and is never sent: a gate denial is a failed tool call inside a turn that continues. */
410	export type AcpStopReason = "end_turn" | "cancelled" | "max_tokens" | "max_turn_requests";
411	
412	/** One verifier run of the turn. */
413	export interface AcpVerifierRun {
414	  command: string;
415	  phase: "before_change" | "completion";
416	  passed: boolean;
417	}
418	
419	export interface AcpVerifier {
420	  status: VerificationStatus;
421	  command?: string;
422	  source?: "configured" | "discovered";
423	  exit_success?: boolean;
424	  output_sha256?: string;
425	  candidate?: string;
426	}
427	
428	/** The validation receipt of an authoritative verifier run, as the receipt's "Validation receipt" section shows it. */
429	export interface AcpValidationReceipt {
430	  id: string;
431	  status: string;
432	  candidate: string | null;
433	}
434	
435	/**
436	 * What Nexus can demonstrate about a turn. `end_turn` says nothing about verification; this object does.
437	 * `receipt_id`: the validation receipt id when one is active, else `turn:<sessionId>:<turnId>`. `turn_id` is null only
438	 * for the last outcome of a loaded session, whose turn id the session record does not carry.
439	 */
440	export interface AcpVerification {
441	  receipt_id: string;
442	  turn_id: string | null;
443	  execution: ExecutionState;
444	  outcome: EngineeringOutcome;
445	  reason?: TurnReason;
446	  unverified_changes_pending: boolean;
447	  verifier: AcpVerifier | null;
448	  verifier_runs: AcpVerifierRun[];
449	  validation_receipt: AcpValidationReceipt | null;
450	}
451	
452	export interface AcpVerificationMeta {
453	  [ACP_META_VERIFICATION]: AcpVerification;
454	}
455	
456	export interface AcpPromptResult {
457	  stopReason: AcpStopReason;
458	  _meta?: AcpVerificationMeta;
459	}
460	
461	/** Result of `_nexus/receipt/get`. Nexus's own type, not part of the specification. Kept in memory for the process only. */
462	export interface NexusReceipt {
463	  receipt_id: string;
464	  session_id: string;
465	  turn_id: string | null;
466	  verification: AcpVerification;
467	  sections: ReceiptSection[];
468	}
469	
470	/** Details of an error, in the standard `data` member (`_meta` is not allowed on a JSON-RPC error). */
471	export interface AcpErrorData {
472	  /** The parameter that failed validation (-32602). */
473	  field?: string;
474	  /** A stable word for the cause, for example a sidecar error code or `sidecar_start_failed`. */
475	  reason?: string;
476	  exit_code?: number | null;
477	  message?: string;
478	}
479	
480	export interface AcpError {
481	  code: AcpErrorCode;
482	  message: string;
483	  data?: AcpErrorData;
484	}
485	
486	export interface AcpResultResponse {
487	  jsonrpc: "2.0";
488	  id: AcpId;
489	  result: AcpInitializeResult | AcpNewSessionResult | AcpLoadSessionResult | AcpPromptResult | NexusReceipt;
490	}
491	
492	/** `id` is null when the request's id could not be read (not JSON, too deep, too long, a batch). */
493	export interface AcpErrorResponse {
494	  jsonrpc: "2.0";
495	  id: AcpId | null;
496	  error: AcpError;
497	}
498	
499	export interface AcpTextContent {
500	  type: "text";
501	  text: string;
502	}
503	
504	export interface AcpAgentMessageChunk {
505	  sessionUpdate: "agent_message_chunk";
506	  content: AcpTextContent;
507	}
508	
509	/** Sent only while replaying a loaded session. */
510	export interface AcpUserMessageChunk {
511	  sessionUpdate: "user_message_chunk";
512	  content: AcpTextContent;
513	}
514	
515	/** The tool kinds of the specification that Nexus uses; `move` and `switch_mode` exist there and no Nexus tool is one. */
516	export type AcpToolKind = "read" | "edit" | "delete" | "search" | "execute" | "think" | "fetch" | "other";
517	export type AcpToolStatus = "pending" | "in_progress" | "completed" | "failed";
518	
519	export interface AcpToolTextContent {
520	  type: "content";
521	  content: AcpTextContent;
522	}
523	
524	/** What Nexus knows about a diff beyond its text. `truncated`: the blocks come from a bounded preview or a cut diff. */
525	export interface AcpDiffInfo {
526	  kind: "added" | "modified" | "deleted";
527	  added: number;
528	  removed: number;
529	  truncated: boolean;
530	}
531	
532	/** `path` is absolute. `oldText` is null for a new file. One block per hunk: the text is the hunk's lines, not the whole file. */
533	export interface AcpToolDiffContent {
534	  type: "diff";
535	  path: string;
536	  oldText: string | null;
537	  newText: string;
538	}
539	
540	export type AcpToolCallContent = AcpToolTextContent | AcpToolDiffContent;
541	
542	/** The tool's name and subject as the sidecar reported them (already redacted and bounded). */
543	export interface AcpToolRawInput {
544	  tool: string;
545	  subject: string;
546	}
547	
548	export interface AcpToolRawOutput {
549	  exit_code?: number | null;
550	  duration_ms?: number;
551	  timed_out?: boolean;
552	  /** The operator declined the call at its approval prompt; it did not run. */
553	  denied?: boolean;
554	}
555	
556	export interface AcpToolCall {
557	  sessionUpdate: "tool_call";
558	  toolCallId: string;
559	  title: string;
560	  kind: AcpToolKind;
561	  status: AcpToolStatus;
562	  rawInput?: AcpToolRawInput;
563	}
564	
565	export interface AcpToolCallUpdateMeta {
566	  [ACP_META_DIFF]?: AcpDiffInfo;
567	}
568	
569	export interface AcpToolCallUpdate {
570	  sessionUpdate: "tool_call_update";
571	  toolCallId: string;
572	  status?: AcpToolStatus;
573	  content?: AcpToolCallContent[];
574	  rawOutput?: AcpToolRawOutput;
575	  _meta?: AcpToolCallUpdateMeta;
576	}
577	
578	/** The verification carrier: no field of its own, the object under `_meta`. */
579	export interface AcpSessionInfoUpdate {
580	  sessionUpdate: typeof ACP_VERIFICATION_CARRIER;
581	  _meta: AcpVerificationMeta;
582	}
583	
584	export type AcpSessionUpdate = AcpAgentMessageChunk | AcpUserMessageChunk | AcpToolCall | AcpToolCallUpdate | AcpSessionInfoUpdate;
585	
586	export interface AcpSessionUpdateNotification {
587	  jsonrpc: "2.0";
588	  method: "session/update";
589	  params: { sessionId: string; update: AcpSessionUpdate };
590	}
591	
592	export interface AcpPermissionOption {
593	  optionId: typeof ACP_ALLOW_ONCE_OPTION_ID | typeof ACP_REJECT_ONCE_OPTION_ID;
594	  name: string;
595	  kind: "allow_once" | "reject_once";
596	}
597	
598	export interface AcpPermissionToolCallMeta {
599	  /** SHA-256 of the canonical `{tool, subject, preview, review}` of the approval this request asks about. */
600	  [ACP_META_APPROVAL_DIGEST]: string;
601	}
602	
603	export interface AcpPermissionToolCall {
604	  toolCallId: string;
605	  title: string;
606	  kind: AcpToolKind;
607	  status: "pending";
608	  content: AcpToolCallContent[];
609	  rawInput: AcpToolRawInput;
610	  _meta: AcpPermissionToolCallMeta;
611	}
612	
613	/** `id` is an integer from a random start, so a reply sent before the request exists matches nothing. */
614	export interface AcpPermissionRequest {
615	  jsonrpc: "2.0";
616	  id: number;
617	  method: "session/request_permission";
618	  params: { sessionId: string; toolCall: AcpPermissionToolCall; options: AcpPermissionOption[] };
619	}
620	
621	/** Everything Nexus sends. It calls no other client method. */
622	export type AcpAgentMessage = AcpResultResponse | AcpErrorResponse | AcpSessionUpdateNotification | AcpPermissionRequest;
623	
624	/** One line of the connection, in either direction: the root of the published schema. */
625	export type AcpAdapterDocument = AcpClientMessage | AcpAgentMessage;
626	
627	/** The exactly two options of every permission request. */
628	export const ACP_PERMISSION_OPTIONS: readonly AcpPermissionOption[] = [
629	  { optionId: ACP_ALLOW_ONCE_OPTION_ID, name: "Allow once", kind: "allow_once" },
630	  { optionId: ACP_REJECT_ONCE_OPTION_ID, name: "Reject", kind: "reject_once" },
631	];
