94	    const name = text("name", true);
95	    if (!name.ok) return name;
96	    const clientVersion = text("version", true);
97	    if (!clientVersion.ok) return clientVersion;
98	    const title = text("title", false);
99	    if (!title.ok) return title;
100	    client = { name: name.value as string, version: clientVersion.value as string, ...(title.value !== undefined ? { title: title.value } : {}) };
101	  }
102	  return ok({ protocolVersion: version, client });
103	}
