207	/**
208	 * A `resource_link` as one line of prompt text. A `file://` URI whose real path lies inside the workspace becomes
209	 * `Referenced file: <path relative to the workspace>`; anything else becomes `Reference: <the URI, on one line>`.
210	 * Nothing is read or fetched: the agent reaches the file, if it wants it, through its own gated tools.
211	 * `workspace` must already be canonical.
212	 */
213	export function resourceLinkLine(uri: string, workspace: string, fs: AcpFs): string {
214	  if (/^file:\/\//i.test(uri)) {
215	    try {
216	      const real = fs.realpath(fileURLToPath(new URL(uri)));
217	      const relative = path.relative(workspace, real);
218	      const inside = relative !== "" && !path.isAbsolute(relative) && relative !== ".." && !relative.startsWith(`..${path.sep}`);
219	      if (inside && !CONTROL.test(relative)) return `Referenced file: ${relative}`;
220	    } catch {
221	      // Not a path that exists here: it stays an opaque reference.
222	    }
223	  }
224	  return `Reference: ${singleLine(uri, ACP_MAX_URI_CHARS)}`;
225	}
226	
227	export interface PromptInput {
228	  sessionId: string;
229	  /** The prompt as the sidecar receives it: text blocks and reference lines, one per line group, in order. */
230	  text: string;
231	}
232	
233	const REFUSED_BLOCKS: Record<string, string> = {
234	  image: "image content is not supported",
235	  audio: "audio content is not supported",
236	  resource: "embedded resources are not supported; send a resource_link",
237	};
238	
239	/**
240	 * `session/prompt`: content blocks to prompt text. `text` is taken as it is; `resource_link` becomes a reference line
241	 * (see `resourceLinkLine`); `image`, `audio` and `resource` are refused, naming the block.
242	 */
243	export function validatePrompt(params: unknown, context: { workspace: string; fs: AcpFs }): Validated<PromptInput> {
244	  const p = record(params);
245	  if (!p) return fail("params", "session/prompt requires a params object");
246	  const sessionId = validateSessionId(member(p, "sessionId"));
247	  if (!sessionId.ok) return sessionId;
248	  const blocks = member(p, "prompt");
249	  if (!Array.isArray(blocks) || blocks.length === 0) return fail("prompt", "prompt must be a non-empty array of content blocks");
250	  if (blocks.length > ACP_MAX_PROMPT_BLOCKS) return fail("prompt", `prompt has more than ${ACP_MAX_PROMPT_BLOCKS} content blocks`);
251	  const parts: string[] = [];
252	  let total = 0;
253	  for (let i = 0; i < blocks.length; i++) {
254	    const field = `prompt[${i}]`;
255	    const block = record(blocks[i]);
256	    if (!block) return fail(field, `prompt block ${i} must be an object`);
257	    const type = member(block, "type");
258	    let part: string;
259	    if (type === "text") {
260	      const text = member(block, "text");
261	      if (typeof text !== "string") return fail(`${field}.text`, `prompt block ${i}: text must be a string`);
262	      if (text.length > ACP_MAX_TEXT_BLOCK_CHARS) return fail(`${field}.text`, `prompt block ${i}: text is longer than ${ACP_MAX_TEXT_BLOCK_CHARS} characters`);
263	      if (text.includes("\0")) return fail(`${field}.text`, `prompt block ${i}: text must not contain a NUL`);
264	      part = text;
265	    } else if (type === "resource_link") {
266	      const uri = member(block, "uri");
267	      if (typeof uri !== "string" || !uri) return fail(`${field}.uri`, `prompt block ${i}: uri must be a non-empty string`);
268	      if (uri.length > ACP_MAX_URI_CHARS) return fail(`${field}.uri`, `prompt block ${i}: uri is longer than ${ACP_MAX_URI_CHARS} characters`);
269	      part = resourceLinkLine(uri, context.workspace, context.fs);
270	    } else if (typeof type === "string" && Object.hasOwn(REFUSED_BLOCKS, type)) {
271	      return fail(field, `prompt block ${i}: ${REFUSED_BLOCKS[type]}`);
272	    } else {
273	      return fail(`${field}.type`, `prompt block ${i}: unknown content type`);
274	    }
275	    total += part.length + (parts.length ? 1 : 0);
276	    if (total > ACP_MAX_PROMPT_CHARS) return fail("prompt", `the prompt is longer than ${ACP_MAX_PROMPT_CHARS} characters`);
277	    parts.push(part);
278	  }
279	  const text = parts.join("\n");
280	  if (!text.trim()) return fail("prompt", "the prompt has no text");
281	  return ok({ sessionId: sessionId.value, text });
282	}
283	
284	export function validateCancel(params: unknown): Validated<{ sessionId: string }> {
285	  const p = record(params);
286	  if (!p) return fail("params", "session/cancel requires a params object");
287	  const sessionId = validateSessionId(member(p, "sessionId"));
288	  return sessionId.ok ? ok({ sessionId: sessionId.value }) : sessionId;
289	}
290	
291	/** `$/cancel_request`: the id of the request to cancel. */
292	export function validateCancelRequest(params: unknown): Validated<{ requestId: AcpId }> {
293	  const p = record(params);
294	  if (!p) return fail("params", "$/cancel_request requires a params object");
295	  const requestId = member(p, "requestId");
296	  if (!isRequestId(requestId)) return fail("requestId", "requestId must be a string or an integer");
297	  return ok({ requestId });
298	}
299	
300	export function validateReceiptGet(params: unknown): Validated<{ sessionId: string; receiptId?: string }> {
301	  const p = record(params);
302	  if (!p) return fail("params", "the receipt request requires a params object");
303	  const sessionId = validateSessionId(member(p, "sessionId"));
304	  if (!sessionId.ok) return sessionId;
305	  if (!present(p, "receiptId")) return ok({ sessionId: sessionId.value });
306	  const receiptId = p.receiptId;
307	  if (typeof receiptId !== "string" || !receiptId || receiptId.length > ACP_MAX_RECEIPT_ID_CHARS || CONTROL.test(receiptId)) {
308	    return fail("receiptId", `receiptId must be a non-empty string of at most ${ACP_MAX_RECEIPT_ID_CHARS} characters`);
309	  }
310	  return ok({ sessionId: sessionId.value, receiptId });
311	}
312	
313	/**
314	 * The shape of the `result` of a reply to `session/request_permission`: `{outcome: {outcome: "selected", optionId}}`
315	 * or `{outcome: {outcome: "cancelled"}}`. Shape only: which option id approves is decided in one place,
316	 * `permissionReplyToCommand` in mapping.ts. There is nobody to send this error to: the caller denies.
317	 */
318	export function validatePermissionResult(result: unknown): Validated<AcpPermissionOutcome> {
319	  const r = record(result);
320	  if (!r) return fail("result", "a permission result must be an object");
321	  const outcome = record(member(r, "outcome"));
322	  if (!outcome) return fail("outcome", "a permission result needs an outcome object");
323	  const kind = member(outcome, "outcome");
324	  if (kind === "cancelled") return ok({ outcome: "cancelled" });
325	  if (kind !== "selected") return fail("outcome.outcome", "the outcome must be selected or cancelled");
326	  const optionId = member(outcome, "optionId");
327	  if (typeof optionId !== "string") return fail("outcome.optionId", "a selected outcome needs a string optionId");
328	  return ok({ outcome: "selected", optionId });
329	}
