275	  if (lines[lines.length - 1] === "") lines.pop();
276	  let oldPath: string | undefined;
277	  let newPath: string | undefined;
278	  let created = false;
279	  let hunk: { before: string[]; after: string[]; beforeEol: boolean; afterEol: boolean; last: "before" | "after" | "both" } | undefined;
280	  let oldLeft = 0;
281	  let newLeft = 0;
282	  const side = (rows: string[], eol: boolean) => (rows.length ? rows.join("\n") + (eol ? "\n" : "") : "");
283	  const flush = () => {
284	    const done = hunk;
285	    hunk = undefined;
286	    oldLeft = 0;
287	    newLeft = 0;
288	    if (!done) return;
289	    const file = newPath ?? oldPath ?? fallbackPath;
290	    if (!file) return;
291	    if (blocks.length >= ACP_MAX_DIFF_BLOCKS) {
292	      truncated = true;
293	      return;
294	    }
295	    blocks.push({ type: "diff", path: path.resolve(workspace, file), oldText: created ? null : side(done.before, done.beforeEol), newText: side(done.after, done.afterEol) });
296	  };
297	  for (const line of lines) {
298	    if (hunk && line.startsWith("\\")) {
299	      // "\ No newline at end of file" describes the line just read.
300	      if (hunk.last !== "after") hunk.beforeEol = false;
301	      if (hunk.last !== "before") hunk.afterEol = false;
302	      continue;
303	    }
304	    if (hunk && (oldLeft > 0 || newLeft > 0)) {
305	      // A hunk header says how many lines follow on each side, so a removed line "-- x" (written "--- x") is content.
306	      if (line.startsWith(" ") || line === "") {
307	        hunk.before.push(line.slice(1));
308	        hunk.after.push(line.slice(1));
309	        hunk.last = "both";
310	        oldLeft = Math.max(0, oldLeft - 1);
311	        newLeft = Math.max(0, newLeft - 1);
312	        continue;
313	      }
314	      if (line.startsWith("-") && oldLeft > 0) {
315	        hunk.before.push(line.slice(1));
316	        hunk.last = "before";
317	        oldLeft--;
318	        continue;
319	      }
320	      if (line.startsWith("+") && newLeft > 0) {
321	        hunk.after.push(line.slice(1));
322	        hunk.last = "after";
323	        newLeft--;
324	        continue;
325	      }
326	      // The hunk ended earlier than its header promised: read this line as structure.
327	    }
328	    if (line.startsWith("@@")) {
329	      flush();
330	      const counts = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
331	      if (!counts) continue;
332	      oldLeft = counts[1] === undefined ? 1 : Number(counts[1]);
333	      newLeft = counts[2] === undefined ? 1 : Number(counts[2]);
334	      hunk = { before: [], after: [], beforeEol: true, afterEol: true, last: "both" };
335	    } else if (line.startsWith("diff --git ")) {
336	      flush();
337	      oldPath = undefined;
338	      newPath = undefined;
339	      created = false;
340	    } else if (line.startsWith("--- ")) {
341	      flush();
342	      const raw = headerPath(line.slice(4));
343	      oldPath = raw === undefined ? undefined : diffSidePath(raw, "a/");
344	      created = raw !== undefined && oldPath === undefined;
345	      newPath = undefined;
346	    } else if (line.startsWith("+++ ")) {
347	      const raw = headerPath(line.slice(4));
348	      newPath = raw === undefined ? undefined : diffSidePath(raw, "b/");
349	    } else if (hunk) {
350	      flush();
351	    }
352	  }
353	  flush();
354	  return { blocks, truncated };
355	}
356	
357	/**
358	 * The diff of a file change as a `tool_call_update`. With the tool call's detail record (`tool.detail`) the full diff
359	 * is used; without it, the bounded preview the `file.diff` event carries. `_meta["nexus/diff"]` says which it was.
360	 */
361	export function fileDiffToUpdate(event: Event<"file.diff">, workspace: string, detail?: Event<"tool.detail">): AcpToolCallUpdate {
362	  const full = detail?.diff;
363	  const { blocks, truncated } = unifiedDiffToBlocks(full ?? event.preview, workspace, event.path);
364	  const cut = truncated || (full === undefined ? event.truncated : (detail?.diff_chars ?? full.length) > full.length);
365	  return {
366	    sessionUpdate: "tool_call_update",
367	    toolCallId: toolCallId(event),
368	    status: "in_progress",
369	    ...(blocks.length ? { content: blocks } : {}),
370	    _meta: { [ACP_META_DIFF]: { kind: event.kind, added: event.added, removed: event.removed, truncated: cut } },
371	  };
372	}
373	
374	function canonicalJson(value: unknown): string {
375	  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
376	  if (value && typeof value === "object") {
377	    const object = value as Record<string, unknown>;
378	    const keys = Object.keys(object).filter((key) => object[key] !== undefined).sort();
379	    return `{${keys.map((key) => `${JSON.stringify(key)}:${canonicalJson(object[key])}`).join(",")}}`;
380	  }
381	  return JSON.stringify(value ?? null);
382	}
383	
384	/** SHA-256 (hex) of the canonical `{tool, subject, preview, review}` of an approval: what the operator was shown. */
385	export function approvalDigest(event: Event<"approval.request">): string {
386	  const { tool, subject, preview, review } = event;
387	  return createHash("sha256").update(canonicalJson({ tool, subject, preview, review })).digest("hex");
388	}
389	
390	/**
391	 * The tool call an approval asks about. `approval.request` carries no call id, so it is bound to the one open
392	 * `tool.start` of the same turn with the same tool and subject; with none, or more than one, the approval's own id is
393	 * used as a synthetic tool call id.
394	 */
395	export function bindApprovalToToolCall(event: Event<"approval.request">, open: ReadonlyArray<Event<"tool.start">>): string {
396	  const matches = open.filter((start) => start.turn_id === event.turn_id && start.tool === event.tool && start.subject === event.subject);
397	  return matches.length === 1 ? toolCallId(matches[0]) : event.id;
398	}
399	
400	function reviewContent(event: Event<"approval.request">, workspace: string): AcpToolCallContent[] {
401	  const review = event.review;
402	  const cut = (truncated: boolean): AcpToolCallContent[] => (truncated ? [textContent("This review text was cut to its size limit; the call's full arguments are larger.")] : []);
403	  switch (review?.kind) {
404	    case "change": {
405	      const hidden = review.before === null && !review.created;
406	      return [
407	        { type: "diff", path: path.resolve(workspace, review.path), oldText: review.before, newText: review.after },
408	        ...(hidden ? [textContent("The file exists, and its current content is not shown (outside the workspace, not a regular file, or too large).")] : []),
409	        ...cut(review.truncated),
410	      ];
411	    }
412	    case "patch":
413	      return [textContent(`Patch for ${singleLine(review.path, 400)}:\n${review.patch}`), ...cut(review.truncated)];
414	    case "command":
415	      return [textContent(review.command)];
416	    case "verifier":
417	      return [textContent([`Verifier: ${review.command}`, review.script, review.detail].filter((part): part is string => typeof part === "string" && part !== "").join("\n\n"))];
418	    case "args":
419	      return [textContent(review.text), ...cut(review.truncated)];
420	    default:
421	      // A review kind this adapter does not know: show the raw arguments rather than nothing.
422	      return [textContent(event.preview)];
423	  }
424	}
425	
426	/**
427	 * `approval.request` as a `session/request_permission` request with exactly the two options allow-once and reject.
428	 * `rpcId` comes from the adapter's `RequestCorrelator`, `toolCallId` from `bindApprovalToToolCall`.
429	 */
430	export function approvalToPermissionRequest(event: Event<"approval.request">, binding: { rpcId: number; sessionId: string; toolCallId: string; workspace: string }): AcpPermissionRequest {
431	  return request(binding.rpcId, "session/request_permission", {
432	    sessionId: binding.sessionId,
433	    toolCall: {
434	      toolCallId: binding.toolCallId,
435	      title: toolTitle(event.tool, event.subject),
436	      kind: toolKind(event.tool),
437	      status: "pending",
438	      content: reviewContent(event, binding.workspace),
439	      rawInput: { tool: event.tool, subject: event.subject },
440	      _meta: { [ACP_META_APPROVAL_DIGEST]: approvalDigest(event) },
441	    },
442	    options: ACP_PERMISSION_OPTIONS.map((option) => ({ ...option })),
443	  });
444	}
445	
446	/** The only two commands a permission reply can become. `always` has the literal type `false`: no caller can widen it. */
447	export type ApprovalCommand = { type: "approve"; id: string; always: false } | { type: "deny"; id: string };
448	
449	/**
450	 * A client's reply to a permission request, as the sidecar command for the approval it answers. THE ONE DECISION POINT:
451	 * `approve` (once, never "always") only for a well-formed `selected` outcome whose option id is the allow-once id Nexus
452	 * offered. Everything else is `deny`: reject, cancelled, an option id that was not offered (`allow_always` included), a
453	 * JSON-RPC error, a malformed or missing result.
454	 *
455	 * The caller must have matched the reply to an open request first (`RequestCorrelator.settle` returned `matched`); a
456	 * stale or unknown reply is never passed here, so it produces no command at all.
457	 */
458	export function permissionReplyToCommand(approvalId: string, reply: { result: unknown } | { error: unknown }): ApprovalCommand {
459	  const deny: ApprovalCommand = { type: "deny", id: approvalId };
460	  if (!Object.hasOwn(reply, "result") || Object.hasOwn(reply, "error")) return deny;
461	  const parsed = validatePermissionResult((reply as { result: unknown }).result);
462	  if (!parsed.ok || parsed.value.outcome !== "selected") return deny;
463	  if (parsed.value.optionId !== ACP_ALLOW_ONCE_OPTION_ID) return deny;
464	  return { type: "approve", id: approvalId, always: false };
465	}
466	
467	/**
468	 * How a prompt request ends for a finished turn: a stop reason, or a JSON-RPC error for a turn that failed.
469	 * `end_turn` says nothing about verification; the verification object does.
470	 */
471	export function turnToStop(turn: TurnResult): { stopReason: AcpStopReason } | { error: AcpError } {
472	  switch (turn.execution) {
473	    case "INTERRUPTED":
474	      return { stopReason: "cancelled" };
475	    case "LIMIT_REACHED":
476	      return { stopReason: "max_turn_requests" };
477	    case "COMPLETED":
478	    case "BLOCKED":
479	      return { stopReason: "end_turn" };
480	    case "FAILED": {
481	      const failure = turn.inferenceFailure;
482	      if (failure?.kind === "output_truncated") return { stopReason: "max_tokens" };
483	      const credentials = failure?.condition === "AUTH_FAILURE" || failure?.httpStatus === 401 || failure?.httpStatus === 403;
484	      const message = bounded(turn.detail || failure?.message || "the turn failed", ACP_MAX_ERROR_MESSAGE_CHARS);
485	      return { error: rpcError(credentials ? ACP_ERROR.AUTH_REQUIRED : ACP_ERROR.INTERNAL_ERROR, message, { reason: turn.reason ?? "FAILED" }) };
486	    }
487	    default:
488	      // An execution state this adapter does not know is never reported as a clean end.
489	      return { error: rpcError(ACP_ERROR.INTERNAL_ERROR, "the turn ended in a state this adapter does not know", { reason: String(turn.execution) }) };
490	  }
491	}
492	
493	/** The title of the receipt section that shows the validation receipt (`validationSection` in cli/src/evidence.ts). */
494	export const VALIDATION_RECEIPT_SECTION = "Validation receipt";
495	
496	/**
497	 * Reads the validation receipt out of the receipt's display rows: the one place that depends on those rows' labels
498	 * (a test pins it against `receiptSections`). Null when no receipt is active.
499	 */
500	export function validationReceiptFromSections(sections: ReadonlyArray<ReceiptSection>): AcpValidationReceipt | null {
501	  const section = sections.find((candidate) => candidate.title === VALIDATION_RECEIPT_SECTION);
502	  const value = (label: string) => section?.rows.find((row) => row[0] === label)?.[1];
503	  const id = value("receipt");
504	  if (!id) return null;
505	  return { id, status: value("status") ?? "", candidate: value("candidate") ?? null };
506	}
507	
508	/**
509	 * The verification object of a turn, from its result and the receipt sections the sidecar returned for it (omitted
510	 * when the receipt could not be fetched: there is then no validation receipt to report). `turnId` is null for the last
511	 * outcome of a loaded session.
512	 */
513	export function verificationFromTurn(input: { sessionId: string; turnId: string | null; turn: TurnResult; sections?: ReadonlyArray<ReceiptSection> }): AcpVerification {
514	  const { turn } = input;
515	  const validation = input.sections ? validationReceiptFromSections(input.sections) : null;
516	  const v = turn.verification;
517	  return {
518	    receipt_id: validation?.id ?? `turn:${input.sessionId}:${input.turnId ?? "last"}`,
519	    turn_id: input.turnId,
520	    execution: turn.execution,
521	    outcome: turn.outcome,
522	    ...(turn.reason ? { reason: turn.reason } : {}),
523	    unverified_changes_pending: turn.unverifiedChangesPending === true,
524	    verifier: v
525	      ? {
526	          status: v.status,
527	          ...(v.command !== undefined ? { command: v.command } : {}),
528	          ...(v.source !== undefined ? { source: v.source } : {}),
529	          ...(v.exitSuccess !== undefined ? { exit_success: v.exitSuccess } : {}),
530	          ...(v.outputSha256 !== undefined ? { output_sha256: v.outputSha256 } : {}),
531	          ...(v.candidateId !== undefined ? { candidate: v.candidateId } : {}),
532	        }
533	      : null,
534	    verifier_runs: (turn.turnEvidence?.verifierRuns ?? []).map((run) => ({ command: run.command, phase: run.phase, passed: run.passed })),
535	    validation_receipt: validation,
536	  };
537	}
538	
539	/** The carrier update: sent just before the prompt response, so a client that reads `_meta` has the verdict first. */
540	export function verificationUpdate(verification: AcpVerification): AcpSessionInfoUpdate {
541	  return { sessionUpdate: ACP_VERIFICATION_CARRIER, _meta: { [ACP_META_VERIFICATION]: verification } };
542	}
543	
544	/** The verdict as plain text, so a client that ignores `_meta` cannot show an unverified completion as plain success. */
545	export function verdictChunk(heading: string, line: string): AcpAgentMessageChunk {
546	  return messageChunk(`\n\n${heading}\n${line}\n`);
547	}
548	
549	export function promptResult(stopReason: AcpStopReason, verification: AcpVerification): AcpPromptResult {
550	  return { stopReason, _meta: { [ACP_META_VERIFICATION]: verification } };
551	}
552	
553	export function nexusReceipt(sessionId: string, verification: AcpVerification, sections: ReadonlyArray<ReceiptSection>): NexusReceipt {
554	  return { receipt_id: verification.receipt_id, session_id: sessionId, turn_id: verification.turn_id, verification, sections: [...sections] };
555	}
556	
557	/**
558	 * A loaded session's `history` as replay updates, oldest first: operator text (prompts and steering) as
559	 * `user_message_chunk`, the agent's text as `agent_message_chunk`, each tool as a completed `tool_call` (`hist-N`),
560	 * and the last outcome as the verification carrier followed by its verdict line. `extent`: conversation entries sent
561	 * of the total the session holds (the replay is partial: ACP_DEVIATION_PARTIAL_REPLAY).
562	 */
563	export function historyToReplay(event: Event<"history">): { updates: AcpSessionUpdate[]; extent: AcpHistoryExtent } {
564	  const updates: AcpSessionUpdate[] = [];
565	  let sent = 0;
566	  let tools = 0;
567	  for (const entry of event.messages) {
568	    switch (entry.role) {
569	      case "user":
570	      case "steering":
571	        sent++;
572	        updates.push({ sessionUpdate: "user_message_chunk", content: { type: "text", text: entry.text } });
573	        break;
574	      case "assistant":
575	        sent++;
576	        updates.push(messageChunk(entry.text));
577	        break;
578	      case "tool": {
579	        const tool = entry.tool ?? "tool";
580	        updates.push({ sessionUpdate: "tool_call", toolCallId: `hist-${++tools}`, title: toolTitle(tool, entry.text), kind: toolKind(tool), status: "completed", rawInput: { tool, subject: entry.text } });
581	        break;
582	      }
583	      case "outcome":
584	        if (entry.turn) updates.push(verificationUpdate(verificationFromTurn({ sessionId: event.session, turnId: null, turn: entry.turn })));
585	        if (entry.heading || entry.text) updates.push(verdictChunk(entry.heading ?? "", entry.text));
586	        break;
587	    }
588	  }
589	  return { updates, extent: { sent, total: Math.max(event.total, sent) } };
590	}
591	
592	/**
593	 * Sidecar error codes as JSON-RPC codes. All are -32603: none is the client's doing (the adapter validates before it
594	 * sends), and -32000 is kept for a credential failure, which arrives as a failed turn (`turnToStop`), not as one of these.
595	 */
596	const SIDECAR_ERROR_CODES: Record<ErrorCode, AcpErrorCode> = {
597	  BAD_REQUEST: ACP_ERROR.INTERNAL_ERROR,
598	  BUSY: ACP_ERROR.INTERNAL_ERROR,
599	  NO_PENDING_APPROVAL: ACP_ERROR.INTERNAL_ERROR,
600	  NOT_FOUND: ACP_ERROR.INTERNAL_ERROR,
601	  INTERNAL: ACP_ERROR.INTERNAL_ERROR,
602	  NO_PROVIDER: ACP_ERROR.INTERNAL_ERROR,
603	  UNSUPPORTED_PROTOCOL: ACP_ERROR.INTERNAL_ERROR,
604	  EXPERIMENTAL_DISABLED: ACP_ERROR.INTERNAL_ERROR,
605	};
606	
607	/** The JSON-RPC error for a sidecar `error` event; `data.reason` is the sidecar's code. */
608	export function sidecarErrorToRpc(event: Event<"error">): AcpError {
609	  const code = Object.hasOwn(SIDECAR_ERROR_CODES, event.code) ? SIDECAR_ERROR_CODES[event.code] : ACP_ERROR.INTERNAL_ERROR;
610	  return rpcError(code, bounded(event.message, ACP_MAX_ERROR_MESSAGE_CHARS), { reason: String(event.code) });
611	}
612	
613	/** The answer to a request ended by `$/cancel_request` (published specification, schema: -32800). */
614	export function cancelledRequestError(id: AcpId): AcpErrorResponse {
615	  return errorResponse(id, rpcError(ACP_ERROR.REQUEST_CANCELLED, "the request was cancelled"));
616	}
