24	
25	export const JSONRPC_VERSION = "2.0";
26	
27	/**
28	 * JSON-RPC error codes Nexus sends. -32601, -32602, -32000 (authentication required) and -32800 (request cancelled,
29	 * for a request ended by `$/cancel_request`) appear verbatim in the published specification; -32700, -32600 and -32603
30	 * are the standard JSON-RPC codes (specification schema page, read as a summary). -32002 exists in the specification
31	 * for `session/close` and is not used here.
