1	/**
2	 * Validation of everything an ACP client sends. Each function takes the raw `params` (or `result`) and returns a typed
3	 * value or a -32602 error naming the field in `data.field`. Error messages are fixed text: no client string is echoed.
4	 *
5	 * Pure. The two checks that need the file system (the canonical form of `cwd`, whether a `file://` link lies inside
6	 * the workspace) take it as an argument (`AcpFs`), and never read a file's content.
7	 */
8	import path from "node:path";
9	import { fileURLToPath } from "node:url";
10	import {
11	  ACP_ERROR,
12	  ACP_MAX_CLIENT_FIELD_CHARS,
13	  ACP_MAX_CWD_CHARS,
14	  ACP_MAX_MCP_SERVERS_INSPECTED,
15	  ACP_MAX_PROMPT_BLOCKS,
16	  ACP_MAX_PROMPT_CHARS,
17	  ACP_MAX_RECEIPT_ID_CHARS,
18	  ACP_MAX_SESSION_ID_CHARS,
19	  ACP_MAX_TEXT_BLOCK_CHARS,
20	  ACP_MAX_URI_CHARS,
21	  ACP_NV_MAX_PROTOCOL_VERSION,
22	  ACP_PROTOCOL_VERSION,
23	} from "./types.js";
24	import type { AcpError, AcpId, AcpMcpServersIgnored, AcpPermissionOutcome } from "./types.js";
25	import { isRequestId } from "./jsonrpc.js";
26	
27	export type Validated<T> = { ok: true; value: T } | { ok: false; error: AcpError };
28	
29	/** The two file-system questions validation asks. Both throw when the path cannot be resolved or examined. */
30	export interface AcpFs {
31	  realpath(file: string): string;
32	  isDirectory(file: string): boolean;
33	}
34	
35	function fail(field: string, message: string): { ok: false; error: AcpError } {
36	  return { ok: false, error: { code: ACP_ERROR.INVALID_PARAMS, message, data: { field } } };
37	}
38	
39	function ok<T>(value: T): { ok: true; value: T } {
40	  return { ok: true, value };
41	}
42	
43	function record(value: unknown): Record<string, unknown> | undefined {
44	  return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : undefined;
45	}
46	
47	/** An own member that is neither absent nor null. */
48	function present(object: Record<string, unknown>, key: string): boolean {
49	  return Object.hasOwn(object, key) && object[key] !== undefined && object[key] !== null;
50	}
51	
52	function member(object: Record<string, unknown>, key: string): unknown {
53	  return Object.hasOwn(object, key) ? object[key] : undefined;
54	}
55	
56	const CONTROL = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]/;
57	const CONTROL_RUNS = /[\u0000-\u001f\u007f-\u009f\u2028\u2029]+/g;
58	
59	/** Text bound for one line of a prompt or a log: control characters (newlines included) become a space, then it is cut. */
60	export function singleLine(text: string, max: number): string {
61	  return text.replace(CONTROL_RUNS, " ").trim().slice(0, max);
62	}
63	
64	export interface InitializeInput {
65	  /** The version the client asked for. The answer is `negotiatedProtocolVersion`. */
66	  protocolVersion: number;
67	  client: { name: string; version: string; title?: string } | null;
68	}
69	
70	/**
71	 * `clientCapabilities` and `_meta` are checked for shape and then dropped: the validated value carries neither, so
72	 * nothing downstream can consult what a client claims about itself.
73	 */
74	export function validateInitialize(params: unknown): Validated<InitializeInput> {
75	  const p = record(params);
76	  if (!p) return fail("params", "initialize requires a params object");
77	  const version = member(p, "protocolVersion");
78	  if (typeof version !== "number" || !Number.isInteger(version) || version < 0 || version > ACP_NV_MAX_PROTOCOL_VERSION) {
79	    return fail("protocolVersion", `protocolVersion must be an integer from 0 to ${ACP_NV_MAX_PROTOCOL_VERSION}`);
80	  }
81	  if (present(p, "clientCapabilities") && !record(p.clientCapabilities)) return fail("clientCapabilities", "clientCapabilities must be an object");
82	  let client: InitializeInput["client"] = null;
83	  if (present(p, "clientInfo")) {
84	    const info = record(p.clientInfo);
85	    if (!info) return fail("clientInfo", "clientInfo must be an object");
86	    const text = (key: string, required: boolean): Validated<string | undefined> => {
87	      if (!present(info, key)) return required ? fail(`clientInfo.${key}`, `clientInfo.${key} must be a non-empty string`) : ok(undefined);
88	      const value = info[key];
89	      if (typeof value !== "string" || !value.trim()) return fail(`clientInfo.${key}`, `clientInfo.${key} must be a non-empty string`);
90	      if (value.length > ACP_MAX_CLIENT_FIELD_CHARS) return fail(`clientInfo.${key}`, `clientInfo.${key} is longer than ${ACP_MAX_CLIENT_FIELD_CHARS} characters`);
91	      if (CONTROL.test(value)) return fail(`clientInfo.${key}`, `clientInfo.${key} must not contain control characters`);
92	      return ok(value);
93	    };
94	    const name = text("name", true);
95	    if (!name.ok) return name;
96	    const clientVersion = text("version", true);
97	    if (!clientVersion.ok) return clientVersion;
98	    const title = text("title", false);
99	    if (!title.ok) return title;
100	    client = { name: name.value as string, version: clientVersion.value as string, ...(title.value !== undefined ? { title: title.value } : {}) };
101	  }
102	  return ok({ protocolVersion: version, client });
103	}
104	
105	/**
106	 * The version to answer `initialize` with: the requested one when Nexus supports it, else the latest Nexus supports
107	 * (published specification, initialization). Nexus supports one version, so this is that version either way.
108	 */
109	export function negotiatedProtocolVersion(_requested: number): typeof ACP_PROTOCOL_VERSION {
110	  return ACP_PROTOCOL_VERSION;
111	}
112	
113	/**
114	 * The part of the `cwd` rule that needs no file system: a string, absolute ("MUST be an absolute path", published
115	 * specification, session-setup), bounded, with no NUL and no line break.
116	 */
117	export function validateCwdShape(value: unknown, field = "cwd"): Validated<string> {
118	  if (typeof value !== "string" || !value) return fail(field, "cwd must be a non-empty string");
119	  if (value.length > ACP_MAX_CWD_CHARS) return fail(field, `cwd is longer than ${ACP_MAX_CWD_CHARS} characters`);
120	  if (/[\0\r\n]/.test(value)) return fail(field, "cwd must not contain a NUL or a line break");
121	  if (!path.isAbsolute(value)) return fail(field, "cwd must be an absolute path");
122	  return ok(value);
123	}
124	
125	/**
126	 * The part that does: the real path of `cwd` (symlinks resolved), which must be a directory. The canonical path is what
127	 * the session runs in, and it passes the shape rule again, because a link can lead to a name the rule refuses.
128	 */
129	export function canonicalCwd(cwd: string, fs: AcpFs, field = "cwd"): Validated<string> {
130	  const shaped = validateCwdShape(cwd, field);
131	  if (!shaped.ok) return shaped;
132	  let real: string;
133	  try {
134	    real = fs.realpath(shaped.value);
135	    if (!fs.isDirectory(real)) return fail(field, "cwd is not a directory");
136	  } catch {
137	    return fail(field, "cwd does not exist or cannot be read");
138	  }
139	  return validateCwdShape(real, field);
140	}
141	
142	/** The exact shape `SessionManager.generateSessionId` writes. `latest`, a prefix and a file name are not session ids here. */
143	const SESSION_ID = /^session_\d{8}_\d{6}_[a-z0-9]{8}$/;
144	
145	export function validateSessionId(value: unknown, field = "sessionId"): Validated<string> {
146	  if (typeof value !== "string" || value.length > ACP_MAX_SESSION_ID_CHARS || !SESSION_ID.test(value)) {
147	    return fail(field, "sessionId must be a complete Nexus session id");
148	  }
149	  return ok(value);
150	}
151	
152	function mcpServers(p: Record<string, unknown>): Validated<AcpMcpServersIgnored> {
153	  const servers = member(p, "mcpServers");
154	  if (!Array.isArray(servers)) return fail("mcpServers", "mcpServers is required and must be an array");
155	  const names: string[] = [];
156	  for (const entry of servers.slice(0, ACP_MAX_MCP_SERVERS_INSPECTED)) {
157	    const name = record(entry) ? member(entry as Record<string, unknown>, "name") : undefined;
158	    names.push(typeof name === "string" ? singleLine(name, ACP_MAX_CLIENT_FIELD_CHARS) : "");
159	  }
160	  return ok({ count: servers.length, names });
161	}
162	
163	/** Session options the specification defines and Nexus does not support: refused, never silently ignored. */
164	function unsupportedSessionOptions(p: Record<string, unknown>): { ok: false; error: AcpError } | undefined {
165	  if (present(p, "additionalDirectories")) {
166	    const directories = p.additionalDirectories;
167	    if (!Array.isArray(directories)) return fail("additionalDirectories", "additionalDirectories must be an array");
168	    if (directories.length > 0) return fail("additionalDirectories", "additional directories are not supported: a session has one workspace, cwd");
169	  }
170	  if (present(p, "systemPrompt")) return fail("systemPrompt", "a client-supplied system prompt is not supported");
171	  return undefined;
172	}
173	
174	export interface NewSessionInput {
175	  /** As sent, shape-checked. Run it through `canonicalCwd` before use. */
176	  cwd: string;
177	  /** What the client asked to connect, for the report only: none of it is connected. */
178	  mcpServers: AcpMcpServersIgnored;
179	}
180	
181	export function validateNewSession(params: unknown): Validated<NewSessionInput> {
182	  const p = record(params);
183	  if (!p) return fail("params", "session/new requires a params object");
184	  const cwd = validateCwdShape(member(p, "cwd"));
185	  if (!cwd.ok) return cwd;
186	  const servers = mcpServers(p);
187	  if (!servers.ok) return servers;
188	  const unsupported = unsupportedSessionOptions(p);
189	  if (unsupported) return unsupported;
190	  return ok({ cwd: cwd.value, mcpServers: servers.value });
191	}
192	
193	export interface LoadSessionInput extends NewSessionInput {
194	  sessionId: string;
195	}
196	
197	export function validateLoadSession(params: unknown): Validated<LoadSessionInput> {
198	  const p = record(params);
199	  if (!p) return fail("params", "session/load requires a params object");
200	  const sessionId = validateSessionId(member(p, "sessionId"));
201	  if (!sessionId.ok) return sessionId;
202	  const rest = validateNewSession(p);
203	  if (!rest.ok) return rest;
204	  return ok({ sessionId: sessionId.value, ...rest.value });
205	}
