265	/**
266	 * A unified diff as ACP diff blocks, one per hunk: `oldText` is the hunk's context and removed lines, `newText` its
267	 * context and added lines; `oldText` is null for a file that did not exist. Paths are made absolute against
268	 * `workspace`; `fallbackPath` names the file when the diff has no header (a cut preview). `truncated`: the diff was cut
269	 * by its producer, or has more hunks than one update carries.
270	 */
271	export function unifiedDiffToBlocks(diff: string, workspace: string, fallbackPath?: string): { blocks: AcpToolDiffContent[]; truncated: boolean } {
272	  const blocks: AcpToolDiffContent[] = [];
273	  let truncated = CAP_MARKER.test(diff);
274	  const lines = diff.split("\n");
275	  if (lines[lines.length - 1] === "") lines.pop();
276	  let oldPath: string | undefined;
277	  let newPath: string | undefined;
278	  let created = false;
279	  let hunk: { before: string[]; after: string[]; beforeEol: boolean; afterEol: boolean; last: "before" | "after" | "both" } | undefined;
280	  let oldLeft = 0;
281	  let newLeft = 0;
282	  const side = (rows: string[], eol: boolean) => (rows.length ? rows.join("\n") + (eol ? "\n" : "") : "");
283	  const flush = () => {
284	    const done = hunk;
285	    hunk = undefined;
286	    oldLeft = 0;
287	    newLeft = 0;
288	    if (!done) return;
289	    const file = newPath ?? oldPath ?? fallbackPath;
290	    if (!file) return;
291	    if (blocks.length >= ACP_MAX_DIFF_BLOCKS) {
292	      truncated = true;
293	      return;
294	    }
295	    blocks.push({ type: "diff", path: path.resolve(workspace, file), oldText: created ? null : side(done.before, done.beforeEol), newText: side(done.after, done.afterEol) });
296	  };
297	  for (const line of lines) {
298	    if (hunk && line.startsWith("\\")) {
299	      // "\ No newline at end of file" describes the line just read.
300	      if (hunk.last !== "after") hunk.beforeEol = false;
301	      if (hunk.last !== "before") hunk.afterEol = false;
302	      continue;
303	    }
304	    if (hunk && (oldLeft > 0 || newLeft > 0)) {
305	      // A hunk header says how many lines follow on each side, so a removed line "-- x" (written "--- x") is content.
306	      if (line.startsWith(" ") || line === "") {
307	        hunk.before.push(line.slice(1));
308	        hunk.after.push(line.slice(1));
309	        hunk.last = "both";
310	        oldLeft = Math.max(0, oldLeft - 1);
311	        newLeft = Math.max(0, newLeft - 1);
312	        continue;
313	      }
314	      if (line.startsWith("-") && oldLeft > 0) {
315	        hunk.before.push(line.slice(1));
316	        hunk.last = "before";
317	        oldLeft--;
318	        continue;
319	      }
320	      if (line.startsWith("+") && newLeft > 0) {
321	        hunk.after.push(line.slice(1));
322	        hunk.last = "after";
323	        newLeft--;
324	        continue;
325	      }
326	      // The hunk ended earlier than its header promised: read this line as structure.
327	    }
328	    if (line.startsWith("@@")) {
329	      flush();
330	      const counts = /^@@ -\d+(?:,(\d+))? \+\d+(?:,(\d+))? @@/.exec(line);
331	      if (!counts) continue;
332	      oldLeft = counts[1] === undefined ? 1 : Number(counts[1]);
333	      newLeft = counts[2] === undefined ? 1 : Number(counts[2]);
334	      hunk = { before: [], after: [], beforeEol: true, afterEol: true, last: "both" };
335	    } else if (line.startsWith("diff --git ")) {
336	      flush();
337	      oldPath = undefined;
338	      newPath = undefined;
339	      created = false;
340	    } else if (line.startsWith("--- ")) {
341	      flush();
342	      const raw = headerPath(line.slice(4));
343	      oldPath = raw === undefined ? undefined : diffSidePath(raw, "a/");
344	      created = raw !== undefined && oldPath === undefined;
345	      newPath = undefined;
346	    } else if (line.startsWith("+++ ")) {
347	      const raw = headerPath(line.slice(4));
348	      newPath = raw === undefined ? undefined : diffSidePath(raw, "b/");
349	    } else if (hunk) {
350	      flush();
351	    }
352	  }
353	  flush();
354	  return { blocks, truncated };
