395	export function bindApprovalToToolCall(event: Event<"approval.request">, open: ReadonlyArray<Event<"tool.start">>): string {
396	  const matches = open.filter((start) => start.turn_id === event.turn_id && start.tool === event.tool && start.subject === event.subject);
397	  return matches.length === 1 ? toolCallId(matches[0]) : event.id;
