400	function reviewContent(event: Event<"approval.request">, workspace: string): AcpToolCallContent[] {
401	  const review = event.review;
402	  const cut = (truncated: boolean): AcpToolCallContent[] => (truncated ? [textContent("This review text was cut to its size limit; the call's full arguments are larger.")] : []);
403	  switch (review?.kind) {
404	    case "change": {
405	      const hidden = review.before === null && !review.created;
406	      return [
407	        { type: "diff", path: path.resolve(workspace, review.path), oldText: review.before, newText: review.after },
408	        ...(hidden ? [textContent("The file exists, and its current content is not shown (outside the workspace, not a regular file, or too large).")] : []),
409	        ...cut(review.truncated),
410	      ];
411	    }
412	    case "patch":
413	      return [textContent(`Patch for ${singleLine(review.path, 400)}:\n${review.patch}`), ...cut(review.truncated)];
414	    case "command":
415	      return [textContent(review.command)];
416	    case "verifier":
417	      return [textContent([`Verifier: ${review.command}`, review.script, review.detail].filter((part): part is string => typeof part === "string" && part !== "").join("\n\n"))];
418	    case "args":
419	      return [textContent(review.text), ...cut(review.truncated)];
420	    default:
421	      // A review kind this adapter does not know: show the raw arguments rather than nothing.
422	      return [textContent(event.preview)];
423	  }
424	}
