467	/**
468	 * How a prompt request ends for a finished turn: a stop reason, or a JSON-RPC error for a turn that failed.
469	 * `end_turn` says nothing about verification; the verification object does.
470	 */
471	export function turnToStop(turn: TurnResult): { stopReason: AcpStopReason } | { error: AcpError } {
472	  switch (turn.execution) {
473	    case "INTERRUPTED":
474	      return { stopReason: "cancelled" };
475	    case "LIMIT_REACHED":
476	      return { stopReason: "max_turn_requests" };
477	    case "COMPLETED":
478	    case "BLOCKED":
479	      return { stopReason: "end_turn" };
480	    case "FAILED": {
481	      const failure = turn.inferenceFailure;
482	      if (failure?.kind === "output_truncated") return { stopReason: "max_tokens" };
483	      const credentials = failure?.condition === "AUTH_FAILURE" || failure?.httpStatus === 401 || failure?.httpStatus === 403;
484	      const message = bounded(turn.detail || failure?.message || "the turn failed", ACP_MAX_ERROR_MESSAGE_CHARS);
485	      return { error: rpcError(credentials ? ACP_ERROR.AUTH_REQUIRED : ACP_ERROR.INTERNAL_ERROR, message, { reason: turn.reason ?? "FAILED" }) };
486	    }
487	    default:
488	      // An execution state this adapter does not know is never reported as a clean end.
489	      return { error: rpcError(ACP_ERROR.INTERNAL_ERROR, "the turn ended in a state this adapter does not know", { reason: String(turn.execution) }) };
490	  }
491	}
