527	          ...(v.command !== undefined ? { command: v.command } : {}),
528	          ...(v.source !== undefined ? { source: v.source } : {}),
529	          ...(v.exitSuccess !== undefined ? { exit_success: v.exitSuccess } : {}),
530	          ...(v.outputSha256 !== undefined ? { output_sha256: v.outputSha256 } : {}),
531	          ...(v.candidateId !== undefined ? { candidate: v.candidateId } : {}),
