557	/**
558	 * A loaded session's `history` as replay updates, oldest first: operator text (prompts and steering) as
559	 * `user_message_chunk`, the agent's text as `agent_message_chunk`, each tool as a completed `tool_call` (`hist-N`),
560	 * and the last outcome as the verification carrier followed by its verdict line. `extent`: conversation entries sent
561	 * of the total the session holds (the replay is partial: ACP_DEVIATION_PARTIAL_REPLAY).
562	 */
563	export function historyToReplay(event: Event<"history">): { updates: AcpSessionUpdate[]; extent: AcpHistoryExtent } {
564	  const updates: AcpSessionUpdate[] = [];
565	  let sent = 0;
566	  let tools = 0;
567	  for (const entry of event.messages) {
568	    switch (entry.role) {
569	      case "user":
570	      case "steering":
571	        sent++;
572	        updates.push({ sessionUpdate: "user_message_chunk", content: { type: "text", text: entry.text } });
573	        break;
574	      case "assistant":
575	        sent++;
576	        updates.push(messageChunk(entry.text));
577	        break;
578	      case "tool": {
579	        const tool = entry.tool ?? "tool";
580	        updates.push({ sessionUpdate: "tool_call", toolCallId: `hist-${++tools}`, title: toolTitle(tool, entry.text), kind: toolKind(tool), status: "completed", rawInput: { tool, subject: entry.text } });
581	        break;
582	      }
583	      case "outcome":
584	        if (entry.turn) updates.push(verificationUpdate(verificationFromTurn({ sessionId: event.session, turnId: null, turn: entry.turn })));
585	        if (entry.heading || entry.text) updates.push(verdictChunk(entry.heading ?? "", entry.text));
586	        break;
587	    }
588	  }
589	  return { updates, extent: { sent, total: Math.max(event.total, sent) } };
590	}
