598	  BUSY: ACP_ERROR.INTERNAL_ERROR,
599	  NO_PENDING_APPROVAL: ACP_ERROR.INTERNAL_ERROR,
600	  NOT_FOUND: ACP_ERROR.INTERNAL_ERROR,
601	  INTERNAL: ACP_ERROR.INTERNAL_ERROR,
602	  NO_PROVIDER: ACP_ERROR.INTERNAL_ERROR,
603	  UNSUPPORTED_PROTOCOL: ACP_ERROR.INTERNAL_ERROR,
