161	      protocol_min: PROTOCOL_MIN, protocol_max: PROTOCOL_MAX, capabilities: [...SIDECAR_CAPABILITIES], experimental: [...this.experimentalOffered],
162	    });
163	    let resumed: { ok: boolean; message: string } | undefined;
164	    try {
165	      resumed = this.resume ? this.resumeSession(this.resume) : undefined;
166	    } catch (err) {
167	      resumed = { ok: false, message: `Could not resume ${this.resume ?? "latest"}: ${errorText(err)}` };
168	    }
169	    // A resume that found nothing to restore is a fresh start: the model detection it skipped runs now.
170	    if (this.resume && !resumed?.ok) void this.app.getAgent().detectPlaceholderModel();
171	    this.emitSessionState();
172	    if (resumed) this.emit({ type: "notice", text: resumed.message });
173	    if (isNexusDirPermissive()) {
174	      this.emit({ type: "notice", text: "your Nexus state is readable by other users; run `nexus doctor --fix`" });
175	    }
176	    this.startupProbe = this.app.getAgent().probeEndpointProblem(this.startupProbeAbort.signal).then((problem) => {
177	      if (problem && !this.shutdownPromise) {
178	        // Only "nothing answers" gates prompts. A rejection on /models is a warning: the chat path refreshes tokens and
179	        // may accept a key the model list refuses, so the turn is left to decide.
180	        if (problem.blocking) this.providerProblem = problem;
181	        this.emit({ type: "notice", ...noProviderNotice(problem) });
182	      }
183	    }).catch(() => {});
184	  }
185	
186	  /** Resolves once no turn is running. */
187	  async idle(): Promise<void> {
188	    while (this.activeTurn) await this.activeTurn;
189	  }
190	
191	  async handleLine(line: string): Promise<void> {
192	    if (!line.trim()) return;
193	    let command: SidecarCommand;
194	    try {
195	      command = parseCommand(line);
196	    } catch (err) {
197	      const id = err instanceof ProtocolError ? err.id : undefined;
198	      this.emit({ type: "error", ...(id ? { id } : {}), code: "BAD_REQUEST", message: (err as Error).message });
199	      return;
200	    }
201	    if (this.unsupportedProtocol && command.type !== "initialize" && command.type !== "shutdown") {
202	      this.emit({
203	        type: "error",
204	        id: "id" in command ? command.id : undefined,
205	        code: "UNSUPPORTED_PROTOCOL",
206	        message: this.unsupportedProtocol,
207	      });
208	      return;
209	    }
210	    switch (command.type) {
211	      case "initialize":
212	        this.initialize(command.id, command.protocol_min ?? PROTOCOL_VERSION, command.protocol_max ?? PROTOCOL_VERSION, command.experimental === true);
213	        return;
214	      case "prompt.submit":
215	        this.submit(command.id, command.text);
216	        return;
217	      case "steer":
218	        this.steer(command.id, command.text);
219	        return;
220	      case "cancel":
221	        this.cancel();
222	        return;
223	      case "approve":
224	        this.resolveApproval(command.id, true, command.always);
225	        return;
226	      case "deny":
227	        this.resolveApproval(command.id, false, false);
228	        return;
229	      case "answer":
230	        // Bound to the decision by id; consumed when a turn reaches it (an unresolved steering conflict: at the next
231	        // turn's start). An id no turn asked about is simply never consumed.
232	        this.app.getAgent().setOperatorAnswers(new Map([[command.question, command.option]]));
233	        this.emit({ type: "notice", text: `Answer recorded for question ${command.question}: ${command.option}. It applies when the next turn reaches that decision.` });
234	        return;
235	      case "checkpoint.choice":
236	        this.resolveCheckpointChoice(command.id, command.choice);
237	        return;
238	      case "slash":
239	        this.slash(command.id, command.command, command.args);
240	        return;
241	      case "tool.detail":
242	      case "receipt":
243	        try {
244	          if (command.type === "tool.detail") this.toolDetail(command.id, command.evidence);
245	          else this.emit({ type: "receipt", id: command.id, sections: this.receipt() });
246	        } catch (err) {
247	          const message = errorText(err);
248	          this.emit({ type: "error", id: command.id, code: "INTERNAL", message });
249	        }
250	        return;
251	      case "models.list":
252	        if (this.app.getAgent().getApprovalMode() === "read-only") {
253	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Provider discovery is disabled while the session is in read-only mode." });
254	          return;
255	        }
256	        void this.modelsList(command.id);
257	        return;
258	      case "model.select":
259	        if (this.app.getAgent().getApprovalMode() === "read-only") {
260	          this.emit({ type: "error", id: command.id, code: "BUSY", message: "Model changes are disabled while the session is in read-only mode." });
261	          return;
262	        }
263	        this.modelSelect(command.id, command.provider, command.model);
264	        return;
265	      case "provider.connect":
266	        if (this.app.getAgent().getApprovalMode() === "read-only") {
267	          this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider connections are disabled while the session is in read-only mode." });
268	          return;
269	        }
270	        void this.providerConnect(command.id, command.provider, command.method, command.key, command.endpoint);
271	        return;
272	      case "provider.cancel":
273	        this.modelLists.get(command.id)?.abort();
274	        this.signIns.get(command.id)?.cancel();
275	        this.signIns.delete(command.id);
276	        cancelLocalEndpointSetup(command.id);
277	        return;
278	      case "provider.local-cancel":
279	        clearLocalEndpointSetup(command.id);
280	        return;
281	      case "provider.disconnect": {
282	        if (this.app.getAgent().getApprovalMode() === "read-only") {
283	          this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: false, message: "Provider changes are disabled while the session is in read-only mode." });
284	          return;
285	        }
286	        const r = disconnect(command.provider);
287	        this.emit({ type: "provider.result", id: command.id, provider: command.provider, success: r.ok, message: r.message });
288	        return;
289	      }
290	      case "shutdown":
291	        await this.shutdown();
292	        return;
293	    }
294	  }
295	
296	  /**
297	   * Negotiation for this connection. It only records connection state, so it is answered at any time, a running turn
298	   * included. Rule: a connection negotiates once. After an `initialized` answer every later `initialize` is refused
299	   * with BAD_REQUEST, because a version or an experimental set that changed mid-connection would leave both sides
300	   * unsure which rules a message in flight was written under. An `initialize` refused with UNSUPPORTED_PROTOCOL
301	   * settled nothing, so the client may send another; the sidecar keeps serving either way.
302	   */
303	  private initialize(id: string, clientMin: number, clientMax: number, experimental: boolean): void {
304	    if (this.negotiated) {
305	      this.emit({ type: "error", id, code: "BAD_REQUEST", message: `initialize was already answered on this connection (protocol ${this.negotiated.protocol}); a connection negotiates once.` });
306	      return;
307	    }
308	    const protocol = Math.min(clientMax, PROTOCOL_MAX);
309	    if (protocol < Math.max(clientMin, PROTOCOL_MIN)) {
310	      this.unsupportedProtocol = `No common protocol version: the client speaks ${clientMin} to ${clientMax}, this sidecar speaks ${PROTOCOL_MIN} to ${PROTOCOL_MAX}.`;
311	      this.emit({
312	        type: "error", id, code: "UNSUPPORTED_PROTOCOL",
313	        message: this.unsupportedProtocol,
314	      });
315	      return;
316	    }
317	    this.negotiated = { protocol, experimental: experimental ? this.experimentalOffered : [] };
318	    this.unsupportedProtocol = undefined;
319	    this.emit({ type: "initialized", id, protocol, capabilities: [...SIDECAR_CAPABILITIES], experimental: [...this.negotiated.experimental] });
320	  }
321	
322	  /**
323	   * The gate every experimental feature's handler calls first: true when this connection enabled `name` (it sent
324	   * `initialize` with `experimental: true` and this sidecar offers `name`). Otherwise it answers `id` with
325	   * EXPERIMENTAL_DISABLED and returns false, and the handler does nothing.
326	   */
327	  requireExperimental(name: string, id?: string): boolean {
328	    if (this.negotiated?.experimental.includes(name)) return true;
329	    const message = this.experimentalOffered.includes(name)
330	      ? `${name} is experimental: send initialize with experimental: true before using it.`
331	      : `${name} is not an experimental feature this sidecar offers.`;
332	    this.emit({ type: "error", ...(id ? { id } : {}), code: "EXPERIMENTAL_DISABLED", message });
333	    return false;
334	  }
335	
336	  /** Sign-ins in progress, by request id (provider.cancel stops one). */
337	  private signIns = new Map<string, { cancel(): void }>();
338	
339	  /** Model-list fetches in flight, by request id: a new list, provider.cancel or shutdown stops them. */
340	  private modelLists = new Map<string, AbortController>();
341	
342	  private async modelsList(id: string): Promise<void> {
343	    // Only the newest list matters: the picker that asked for an older one is gone.
344	    for (const older of this.modelLists.values()) older.abort();
345	    const controller = new AbortController();
346	    this.modelLists.set(id, controller);
347	    try {
348	      const catalog = await buildCatalog(this.app.getConfig(), { signal: controller.signal });
349	      if (!controller.signal.aborted) this.emit({ type: "models.catalog", id, ...catalog });
350	    } catch (err) {
351	      if (!controller.signal.aborted) this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) });
352	    } finally {
353	      if (this.modelLists.get(id) === controller) this.modelLists.delete(id);
354	    }
355	  }
356	
357	  /** Switching models between turns is the operator's choice; during a turn it is refused like any command. */
358	  private modelSelect(id: string, provider: string, model: string): void {
359	    if (this.rejectBusy(id)) return;
360	    const r = selectModel(this.app.getAgent(), this.app.getConfig(), { provider, model });
361	    if (!r.ok && provider === "appliance") clearLocalEndpointSetupAfterSelectionFailure();
362	    this.emit({ type: "model.result", id, success: r.ok, message: r.message });
363	    if (r.ok) this.emitSessionState();
364	  }
