366	  private async providerConnect(id: string, provider: string, method: string, key?: string, endpoint?: string): Promise<void> {
367	    const result = (success: boolean, message: string) =>
368	      this.emit({ type: "provider.result", id, provider: provider, success, message: message });
369	    try {
370	      if (provider === "appliance" && method === "local-endpoint") {
371	        if (!endpoint) {
372	          result(false, "An endpoint URL is required.");
373	          return;
374	        }
375	        const prepared = await prepareLocalEndpoint(this.app.getConfig(), endpoint, key ?? "", id);
376	        if (!prepared.cancelled) result(prepared.ok, prepared.message);
377	        return;
378	      }
379	      if (method === "api-key") {
380	        const r = await connectWithKey(this.app.getConfig(), provider, key ?? "");
381	        result(r.ok, r.message);
382	        return;
383	      }
384	      if (endpoint !== undefined) {
385	        result(false, "Endpoint URLs are only accepted for local endpoint setup.");
386	        return;
387	      }
388	      const signIn = await startSignIn(this.app.getConfig(), provider, method);
389	      this.signIns.set(id, signIn);
390	      this.emit({
391	        type: "provider.auth",
392	        id,
393	        provider,
394	        url: signIn.prompt.url,
395	        ...(signIn.prompt.userCode ? { user_code: signIn.prompt.userCode } : {}),
396	        instructions: signIn.prompt.instructions,
397	      });
398	      const r = await signIn.done;
399	      this.signIns.delete(id);
400	      result(r.ok, r.message);
401	    } catch (err) {
402	      this.signIns.delete(id);
403	      result(false, String((err as Error).message ?? err));
404	    }
405	  }
406	
407	  private steerAck(id: string, status: SteerStatus, message: string, text?: string): void {
408	    this.emit({ type: "steer.ack", id, status, message, ...(text !== undefined ? { text: text } : {}) });
409	  }
410	
411	  /**
412	   * Operator steering while work runs. Held by the agent and applied at its next step boundary; if the turn is already
413	   * finishing it starts a follow-up turn; if nothing is running it starts a turn. Never applied twice, never dropped
414	   * without telling the client (which then gets the text back).
415	   */
416	  private steer(id: string, text: string): void {
417	    // Seen by this process, or recorded in the session's objective ledger (applied before a restart and resume).
418	    if (this.steerSeen.has(id) || this.app.getAgent().getObjective()?.steering.some((s) => s.id === id) || this.app.getAgent().getObjective()?.steeringConflicts?.some((c) => c.id === id)) {
419	      this.steerAck(id, "duplicate", "Already received; it is not applied again.");
420	      return;
421	    }
422	    this.steerSeen.add(id);
423	    if (this.shutdownPromise) {
424	      this.steerAck(id, "rejected", "The sidecar is shutting down; your message was not applied.", text);
425	      return;
426	    }
427	    if (!this.activeTurn) {
428	      this.runJob(id, undefined, (signal) =>
429	        this.gatedTurn(id, text, signal, {
430	          admitted: () => {
431	            this.history.push(text.trim());
432	            this.steerAck(id, "applied", "Nothing was running, so your message started a new turn.");
433	          },
434	          refused: (message) => this.steerAck(id, "cancelled", `${message} Your message is back in the composer.`, text),
435	        }),
436	      );
437	      return;
438	    }
439	    if (this.activeSpec) {
440	      const name = this.activeSpec.name === "!" ? "!" : `/${this.activeSpec.name}`;
441	      this.steerAck(id, "rejected", `${name} is running, and steering applies to agent turns; your message is back in the composer.`, text);
442	      return;
443	    }
444	    // Messages already waiting for their own turn come first: a later one never overtakes them.
445	    if (this.followUps.length) {
446	      this.followUps.push({ id, text });
447	      this.steerAck(id, "deferred", "The turn is finishing; your message runs as its own follow-up turn once the turns before it have ended.");
448	      return;
449	    }
450	    const queued = this.app.getAgent().queueSteering(id, text);
451	    if (queued.status === "queued") {
452	      this.history.push(text.trim());
453	      this.steerAck(id, "queued", "Steering queued; the agent applies it at its next step.");
454	      return;
455	    }
456	    if (queued.status === "duplicate") {
457	      this.steerAck(id, "duplicate", "Already received; it is not applied again.");
458	      return;
459	    }
460	    if (queued.status === "conflict") {
461	      const negates = (queued.requirements ?? []).join(", ");
462	      if (queued.held) this.steerAck(id, "held", `Held: this would drop ${negates}. Nothing changed; decide on the approval prompt.`);
463	      else this.steerAck(id, "rejected", `This would drop ${negates}, which needs your decision, and none could be asked; the conflict is recorded and nothing changed. Your message is back in the composer.`, text);
464	      return;
465	    }
466	    if (queued.status === "no_active_turn") {
467	      this.followUps.push({ id, text });
468	      this.steerAck(id, "deferred", "The turn is finishing; your message runs as its own follow-up turn once the turns before it have ended.");
469	      return;
470	    }
471	    const unhandled: never = queued.status;
472	    throw new Error(`unhandled steering status ${String(unhandled)}`);
473	  }
474	
475	  /**
476	   * Runs the oldest deferred message as its own follow-up turn under its own id. Later ones wait: when this turn
477	   * ends the settle path starts the next, so each message is a separate user message and a separate turn, in the
478	   * order sent, never joined into one (D-18).
479	   */
480	  private startFollowUp(): void {
481	    const next = this.followUps.shift()!;
482	    this.runJob(next.id, undefined, (signal) =>
483	      this.gatedTurn(next.id, next.text, signal, {
484	        admitted: () => {
485	          this.history.push(next.text.trim());
486	          this.steerAck(next.id, "applied", "Applied as a follow-up turn.");
487	        },
488	        refused: (message) => {
489	          // The messages behind it would be refused too: return them now, in order, rather than probing again for each.
490	          for (const f of [next, ...this.followUps.splice(0)]) this.steerAck(f.id, "cancelled", `${message} Your message is back in the composer.`, f.text);
491	        },
492	      }),
493	    );
494	  }
495	
496	  private cancel(): void {
497	    for (const f of this.followUps) this.steerAck(f.id, "cancelled", "Cancelled with the turn before it could start; your message is back in the composer.", f.text);
498	    this.followUps = [];
499	    this.dropPendingCompactions("cancelled with the running work");
500	    const spec = this.activeSpec;
501	    if (this.activeTurn && spec && !spec.cancellable) {
502	      const name = spec.name === "!" ? "!" : `/${spec.name}`;
503	      this.emit({ type: "notice", text: `${name} cannot be cancelled; it finishes on its own.` });
504	      return;
505	    }
506	    this.turnAbort?.abort(new Error("operator cancel"));
507	  }
508	
509	  /** Reports BUSY for `id` when a turn or command is running or the sidecar is shutting down. */
510	  private rejectBusy(id: string): boolean {
511	    if (!this.shutdownPromise && !this.activeTurn) return false;
512	    const message = this.shutdownPromise ? "The sidecar is shutting down." : "A turn or command is running; cancel it or wait for its result.";
513	    this.emit({ type: "error", id, code: "BUSY", message });
514	    return true;
515	  }
516	
517	  /**
518	   * /compact while a turn or command runs. During an agent turn the agent holds it until the turn's next step boundary
519	   * (after the in-flight inference and its tool batch, approvals included, have settled) or the turn's end. While another
520	   * command runs, it waits here and runs as its own job afterwards. Each request is acknowledged now (notice) and gets
521	   * its outcome later (slash.result for its id). A duplicate shares the queued request's outcome; at most one request
522	   * per kind (default, --llm) waits; cancellation and shutdown end waiting requests with that outcome.
523	   */
524	  private queueCompaction(id: string, llm: boolean): void {
525	    const queued = this.app.getAgent().requestCompaction(id, llm);
526	    if (queued.status !== "no_active_turn") {
527	      this.emit({ type: "notice", text: queued.message });
528	      return;
529	    }
530	    const existing = this.pendingCompactions.find((p) => p.llm === llm);
531	    if (existing) {
532	      existing.ids.push(id);
533	      this.emit({ type: "notice", text: `A /compact${llm ? " --llm" : ""} is already waiting; this request shares its outcome.` });
534	      return;
535	    }
536	    this.pendingCompactions.push({ ids: [id], llm });
537	    this.emit({ type: "notice", text: `/compact${llm ? " --llm" : ""} queued: it runs when the current command finishes.` });
538	  }
539	
540	  private compactionResult(ids: string[], ok: boolean, message: string): void {
541	    for (const id of ids) this.emit({ type: "slash.result", id, command: "compact", success: ok, output: message });
542	  }
543	
544	  /** Ends waiting /compact requests that will not run. */
545	  private dropPendingCompactions(reason: string): void {
546	    for (const p of this.pendingCompactions) this.compactionResult(p.ids, false, `/compact was not run: ${reason}.`);
547	    this.pendingCompactions = [];
548	  }
549	
550	  /** Runs one turn or command as the session's only activity. Busy is reported before `body` starts. */
551	  private runJob(id: string, spec: SlashSpec | undefined, body: (signal: AbortSignal) => Promise<void>): void {
552	    const abort = new AbortController();
553	    this.turnAbort = abort;
554	    this.activeSpec = spec;
555	    let settle!: () => void;
556	    this.activeTurn = new Promise<void>((resolve) => {
557	      settle = resolve;
558	    });
559	    this.emitSessionState();
560	    void body(abort.signal)
561	      .catch((err) => this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) }))
562	      .finally(() => {
563	        this.activeTurn = undefined;
564	        this.turnAbort = undefined;
565	        this.activeSpec = undefined;
566	        // Queued /compact runs before anything else starts, without an idle state in between.
567	        if (this.pendingCompactions.length && !this.shutdownPromise) {
568	          const pending = this.pendingCompactions;
569	          this.pendingCompactions = [];
570	          settle();
571	          this.runJob(pending[0].ids[0], findSlash("compact"), async (signal) => {
572	            for (const p of pending) {
573	              const result = await this.app.getAgent().compactNow(p.llm, signal);
574	              this.compactionResult(p.ids, result.ok, result.message);
575	            }
576	          });
577	          return;
578	        }
579	        if (this.pendingCompactions.length) this.dropPendingCompactions("the sidecar is shutting down");
580	        // Deferred steering starts its turn without an idle state in between, so nothing can slip into the gap.
581	        if (this.followUps.length && !this.shutdownPromise) {
582	          settle();
583	          this.startFollowUp();
584	          return;
585	        }
586	        this.emitSessionState();
587	        settle();
588	      });
589	  }
590	
591	  private submit(id: string, text: string): void {
592	    if (this.rejectBusy(id)) return;
593	    this.runJob(id, undefined, (signal) =>
594	      this.gatedTurn(id, text, signal, {
595	        admitted: () => this.history.push(text.trim()),
596	        refused: (message) => this.emit({ type: "error", id, code: "NO_PROVIDER", message }),
597	      }),
598	    );
599	  }
600	
601	  /**
602	   * The one way a prompt, a steer that starts a turn and a follow-up start a turn. When start-up found nothing answering,
603	   * it waits for that probe, asks again (the operator may have connected a provider or started a server since) and
604	   * refuses with the reason rather than entering a retry loop. A cancelled probe says nothing about the provider: the
605	   * gate stays and the turn does not run.
606	   */
607	  private async gatedTurn(
608	    id: string,
609	    text: string | any[],
610	    signal: AbortSignal,
611	    hooks: { admitted?: () => void; refused: (message: string) => void },
612	    turnArgs?: { title?: string; checkpoint?: string; step?: boolean },
613	  ): Promise<void> {
614	    // Cancelled while the gate was checking: the message is reported back (never silently dropped), not run.
615	    const cancelled = "Cancelled before it was sent.";
616	    await this.startupProbe;
617	    // With no known problem a cancel is the turn's own business (it reports INTERRUPTED); only the gate reports it here.
618	    if (this.providerProblem) {
619	      const problem = await this.app.getAgent().probeEndpointProblem(signal);
620	      if (signal.aborted) return hooks.refused(cancelled);

