40	import { SidecarServer } from "../../src/sidecar.js";
41	import { PROTOCOL_VERSION } from "../../src/protocol.js";
42	import { startGateway, makeRepo, makeHome, type Reply } from "./fixtures.js";
43	import { validate, type Schema } from "./json_schema.js";
44	
45	export interface WireStep {
46	  send?: Record<string, unknown>;
47	  raw?: string;
48	  malformed?: string;
49	  expect: unknown[];
50	  closes?: true;
51	}
52	
53	export interface WireRecording {
54	  description: string;
55	  gateway: Reply[];
56	  steps: WireStep[];
57	}
58	
59	/**
60	 * Values that differ between two runs of the same steps, by event type and field path: the recorder writes the
61	 * placeholder instead of the value. Everything not listed is recorded, and replayed, exactly.
62	 */
63	const VARIES: Record<string, Record<string, string>> = {
64	  // `commands` is the slash catalogue of this build, not part of the session; the schema still checks each entry.
65	  hello: { pid: "<any:number>", commands: "<any:array>" },
66	  // `context_tokens` is an estimate over the system prompt, which changes with the prompt text and the host.
67	  "session.state": { session: "<id:session>", context_tokens: "<any:number>" },
68	  "turn.result": {
