76	const WIRE_DIR = fileURLToPath(new URL("../fixtures/wire/", import.meta.url));
77	const SCHEMA_FILE = fileURLToPath(new URL(`../../../docs/protocol/sidecar-v${PROTOCOL_VERSION}.schema.json`, import.meta.url));
78	const schema: Schema = JSON.parse(fs.readFileSync(SCHEMA_FILE, "utf8"));
79	const EVENT = { $ref: "#/$defs/SidecarEvent" };
80	const COMMAND = { $ref: "#/$defs/SidecarCommand" };
81	
82	export function recordingNames(): string[] {
83	  return fs.readdirSync(WIRE_DIR).filter((file) => file.endsWith(".json")).map((file) => file.slice(0, -".json".length)).sort();
84	}
