92	/** One event (or reply) per line, so a changed event is one changed line in review. */
93	export function recordingText(recording: WireRecording): string {
94	  const list = (items: unknown[], indent: string) => (items.length ? `[\n${items.map((item) => `${indent}  ${JSON.stringify(item)}`).join(",\n")}\n${indent}]` : "[]");
95	  const steps = recording.steps.map((step) => {
96	    const fields = [
97	      ...(step.send !== undefined ? [`"send": ${JSON.stringify(step.send)}`] : []),
98	      ...(step.raw !== undefined ? [`"raw": ${JSON.stringify(step.raw)}`] : []),
99	      ...(step.malformed !== undefined ? [`"malformed": ${JSON.stringify(step.malformed)}`] : []),
100	      `"expect": ${list(step.expect, "      ")}`,
101	      ...(step.closes ? [`"closes": true`] : []),
102	    ];
103	    return `    {\n${fields.map((field) => `      ${field}`).join(",\n")}\n    }`;
104	  });
105	  return `{\n  "description": ${JSON.stringify(recording.description)},\n  "gateway": ${list(recording.gateway, "  ")},\n  "steps": [\n${steps.join(",\n")}\n  ]\n}\n`;
