112	interface Observed {
113	  /** Per step: the events the sidecar emitted, and whether it shut down during the step. */
114	  steps: Array<{ events: any[]; closed: boolean }>;
115	  workspace: string;
116	  /** Chat requests the sidecar made to the scripted model. */
117	  modelRequests: number;
118	  /** Lines and events that break the schema rules above. */
119	  problems: string[];
120	}
121	
122	const stepLabel = (step: WireStep, index: number): string =>
123	  `step ${index + 1} (${step.send ? `send ${String(step.send.type)}` : step.raw !== undefined ? "raw line" : "connect"})`;
124	
125	/** Runs the recording's steps against a real sidecar in a temporary workspace and HOME. */
126	async function observe(recording: WireRecording): Promise<Observed> {
127	  const gw = await startGateway((n) => recording.gateway[n - 1] ?? { kind: "http", status: 500, body: '{"error":"the recording scripts no further model reply"}' });
128	  const repo = makeRepo();
129	  // The branch name `git init` picks is host configuration; the recording must not depend on it.
130	  execFileSync("git", ["branch", "-M", "main"], { cwd: repo, stdio: "ignore" });
131	  const home = makeHome();
132	  const previousHome = process.env.HOME;
133	  process.env.HOME = home;
134	  const app = new ApplicationCore({ endpoint: gw.url, model: "m", maxSteps: 6, temperature: 0, workspace: repo, shell: "bash", approvalMode: "auto", fullAccess: true } as any);
135	  const events: any[] = [];
136	  let closed = false;
137	  const server = new SidecarServer({ app, mode: "auto", write: (line) => events.push(JSON.parse(line)), onShutdown: () => { closed = true; } });
138	  const observed: Observed = { steps: [], workspace: repo, modelRequests: 0, problems: [] };
139	  try {
140	    for (const [index, step] of recording.steps.entries()) {
141	      const label = stepLabel(step, index);
142	      const from = events.length;
143	      closed = false;
144	      if (step.send === undefined && step.raw === undefined) {
145	        if (index !== 0) throw new Error(`${label}: only the first step may be the connect step (no send, no raw)`);
146	        server.start();
147	      } else {
148	        if (index === 0) throw new Error("step 1 must be the connect step (no send, no raw)");
149	        const line = step.raw ?? JSON.stringify(step.send);
150	        let errors: string[];
151	        try {
152	          errors = validate(JSON.parse(line), COMMAND, schema);
153	        } catch {
154	          errors = ["not JSON"];
155	        }
156	        if (step.malformed === undefined && errors.length) observed.problems.push(`${label}: the line is not a valid command (${errors.join("; ")}); mark it "malformed" if that is intended`);
157	        if (step.malformed !== undefined && !errors.length) observed.problems.push(`${label}: marked malformed, but the line is a valid command`);
158	        await server.handleLine(line);
159	      }
160	      await server.idle();
161	      const emitted = events.slice(from);
162	      emitted.forEach((event, at) => {
163	        const errors = validate(event, EVENT, schema);
164	        if (errors.length) observed.problems.push(`${label}, event ${at + 1} (${String(event?.type)}): not valid against the schema: ${errors.join("; ")}`);
165	      });
166	      observed.steps.push({ events: emitted, closed });
167	    }
168	  } finally {
169	    await server.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "cancel" }));
170	    await server.idle();
171	    app.shutdown();
172	    observed.modelRequests = gw.requests.length;
173	    await gw.close();
174	    if (previousHome === undefined) delete process.env.HOME;
175	    else process.env.HOME = previousHome;
176	    fs.rmSync(repo, { recursive: true, force: true });
177	    fs.rmSync(home, { recursive: true, force: true });
178	  }
179	  return observed;
180	}
181	
182	const jsonType = (value: unknown): string => (value === null ? "null" : Array.isArray(value) ? "array" : typeof value);
183	const shown = (value: unknown): string => {
184	  const text = JSON.stringify(value);
185	  return text.length > 120 ? `${text.slice(0, 120)}…` : text;
186	};
187	
188	/** Where `actual` first departs from `expected` (see "Matching" above), or undefined. `ids` holds the captures so far. */
189	function mismatch(expected: unknown, actual: unknown, at: string, workspace: string, ids: Map<string, string>): string | undefined {
190	  if (typeof expected === "string") {
191	    const any = /^<any:(string|number|array)>$/.exec(expected);
192	    if (any) return jsonType(actual) === any[1] ? undefined : `${at}: expected any ${any[1]}, got ${shown(actual)}`;
193	    const id = /^<id:([\w-]+)>$/.exec(expected);
194	    if (id) {
195	      if (typeof actual !== "string" || !actual) return `${at}: expected a non-empty string for ${expected}, got ${shown(actual)}`;
196	      const bound = ids.get(id[1]);
197	      if (bound === undefined) ids.set(id[1], actual);
198	      else if (bound !== actual) return `${at}: expected ${expected} to be ${shown(bound)} again, got ${shown(actual)}`;
199	      return undefined;
200	    }
201	    const literal = expected.replaceAll("<workspace-name>", path.basename(workspace)).replaceAll("<workspace>", workspace);
202	    return literal === actual ? undefined : `${at}: expected ${shown(literal)}, got ${shown(actual)}`;
203	  }
204	  if (jsonType(expected) !== jsonType(actual)) return `${at}: expected ${shown(expected)}, got ${shown(actual)}`;
205	  if (Array.isArray(expected)) {
206	    const items = actual as unknown[];
207	    if (expected.length !== items.length) return `${at}: expected ${expected.length} items, got ${items.length}`;
208	    for (let i = 0; i < expected.length; i += 1) {
209	      const found = mismatch(expected[i], items[i], `${at}[${i}]`, workspace, ids);
210	      if (found) return found;
211	    }
212	    return undefined;
213	  }
214	  if (expected && typeof expected === "object") {
215	    const want = expected as Record<string, unknown>;
216	    const got = actual as Record<string, unknown>;
217	    for (const key of Object.keys(got)) if (!Object.hasOwn(want, key)) return `${at}: unexpected field ${key} = ${shown(got[key])}`;
218	    for (const key of Object.keys(want)) {
219	      if (!Object.hasOwn(got, key)) return `${at}: missing field ${key}`;
220	      const found = mismatch(want[key], got[key], `${at}.${key}`, workspace, ids);
221	      if (found) return found;
222	    }
223	    return undefined;
224	  }
225	  return expected === actual ? undefined : `${at}: expected ${shown(expected)}, got ${shown(actual)}`;
226	}
227	
228	/** Every way the observed run departs from the recording, each naming its step; empty when the replay conforms. */
229	function divergences(recording: WireRecording, observed: Observed): string[] {
230	  const found = [...observed.problems];
231	  const ids = new Map<string, string>();
232	  recording.steps.forEach((step, index) => {
233	    const label = stepLabel(step, index);
234	    const { events, closed } = observed.steps[index];
235	    const types = (list: any[]) => list.map((event) => String(event?.type)).join(", ") || "nothing";
236	    if (events.length !== step.expect.length) {
237	      found.push(`${label}: expected ${step.expect.length} events (${types(step.expect)}), the sidecar sent ${events.length} (${types(events)})`);
238	    } else {
239	      events.forEach((event, at) => {
240	        const problem = mismatch(step.expect[at], event, "$", observed.workspace, ids);
241	        if (problem) found.push(`${label}, event ${at + 1} (${String(event?.type)}): ${problem}`);
242	      });
243	    }
244	    if (closed !== Boolean(step.closes)) found.push(`${label}: ${closed ? "the sidecar shut down, which the recording does not expect" : "the recording expects the sidecar to shut down, and it did not"}`);
245	  });
246	  if (observed.modelRequests !== recording.gateway.length) found.push(`the sidecar made ${observed.modelRequests} model requests; the recording scripts ${recording.gateway.length}`);
247	  return found;
248	}
249	
250	/** Replays the recording; throws an error listing each divergence with its step number. */
251	export async function replay(recording: WireRecording): Promise<void> {
252	  const found = divergences(recording, await observe(recording));
253	  if (found.length) throw new Error(`the replay diverges from the recording:\n${found.join("\n")}`);
254	}
255	
256	/** Runs the recording's steps and returns it with `expect` and `closes` taken from what the sidecar really did. */
257	export async function record(recording: WireRecording): Promise<WireRecording> {
258	  const observed = await observe(recording);
259	  if (observed.problems.length) throw new Error(observed.problems.join("\n"));
260	  const captured = new Map<string, string>();
261	  const at = (event: any, dotted: string) => {
262	    const keys = dotted.split(".");
263	    const last = keys.pop() as string;
264	    const holder = keys.reduce((node, key) => (node && typeof node === "object" ? node[key] : undefined), event);
265	    return holder && typeof holder === "object" && Object.hasOwn(holder, last) ? { holder, last } : undefined;
266	  };
267	  // First the listed fields (which also gives each captured id its value), then every other place those values appear.
268	  const steps = observed.steps.map(({ events }) => structuredClone(events));
269	  for (const event of steps.flat()) {
270	    for (const [dotted, placeholder] of Object.entries(VARIES[event.type] ?? {})) {
271	      const found = at(event, dotted);
272	      if (!found) continue;
273	      const id = /^<id:([\w-]+)>$/.exec(placeholder);
274	      if (id && typeof found.holder[found.last] === "string") captured.set(found.holder[found.last], placeholder);
275	      found.holder[found.last] = placeholder;
276	    }
277	  }
278	  const name = path.basename(observed.workspace);
279	  const generalize = (value: unknown): unknown => {
280	    if (typeof value === "string") return captured.get(value) ?? value.replaceAll(observed.workspace, "<workspace>").replaceAll(name, "<workspace-name>");
281	    if (Array.isArray(value)) return value.map(generalize);
282	    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([key, nested]) => [key, generalize(nested)]));
283	    return value;
284	  };
285	  return {
286	    description: recording.description,
287	    gateway: recording.gateway,
288	    steps: recording.steps.map((step, index) => {
289	      const { closes: _closes, ...kept } = step;
290	      return { ...kept, expect: generalize(steps[index]) as unknown[], ...(observed.steps[index].closed ? { closes: true as const } : {}) };
291	    }),
292	  };
293	}
