194	export async function waitUntil(cond: () => boolean, timeoutMs = 10000): Promise<void> {
195	  const deadline = Date.now() + timeoutMs;
196	  while (!cond()) {
197	    if (Date.now() > deadline) throw new Error("timed out");
198	    await new Promise((r) => setTimeout(r, 10));
199	  }
200	}
