550	  /** Runs one turn or command as the session's only activity. Busy is reported before `body` starts. */
551	  private runJob(id: string, spec: SlashSpec | undefined, body: (signal: AbortSignal) => Promise<void>): void {
552	    const abort = new AbortController();
553	    this.turnAbort = abort;
554	    this.activeSpec = spec;
555	    let settle!: () => void;
556	    this.activeTurn = new Promise<void>((resolve) => {
557	      settle = resolve;
558	    });
559	    this.emitSessionState();
560	    void body(abort.signal)
561	      .catch((err) => this.emit({ type: "error", id, code: "INTERNAL", message: errorText(err) }))
562	      .finally(() => {
563	        this.activeTurn = undefined;
564	        this.turnAbort = undefined;
565	        this.activeSpec = undefined;
566	        // Queued /compact runs before anything else starts, without an idle state in between.
567	        if (this.pendingCompactions.length && !this.shutdownPromise) {
568	          const pending = this.pendingCompactions;
569	          this.pendingCompactions = [];
570	          settle();
571	          this.runJob(pending[0].ids[0], findSlash("compact"), async (signal) => {
572	            for (const p of pending) {
573	              const result = await this.app.getAgent().compactNow(p.llm, signal);
574	              this.compactionResult(p.ids, result.ok, result.message);
575	            }
576	          });
577	          return;
578	        }
579	        if (this.pendingCompactions.length) this.dropPendingCompactions("the sidecar is shutting down");
580	        // Deferred steering starts its turn without an idle state in between, so nothing can slip into the gap.
581	        if (this.followUps.length && !this.shutdownPromise) {
582	          settle();
583	          this.startFollowUp();
584	          return;
585	        }
586	        this.emitSessionState();
587	        settle();
588	      });
589	  }
