125	/** Runs the recording's steps against a real sidecar in a temporary workspace and HOME. */
126	async function observe(recording: WireRecording): Promise<Observed> {
127	  const gw = await startGateway((n) => recording.gateway[n - 1] ?? { kind: "http", status: 500, body: '{"error":"the recording scripts no further model reply"}' });
128	  const repo = makeRepo();
129	  // The branch name `git init` picks is host configuration; the recording must not depend on it.
130	  execFileSync("git", ["branch", "-M", "main"], { cwd: repo, stdio: "ignore" });
131	  const home = makeHome();
132	  const previousHome = process.env.HOME;
133	  process.env.HOME = home;
134	  const app = new ApplicationCore({ endpoint: gw.url, model: "m", maxSteps: 6, temperature: 0, workspace: repo, shell: "bash", approvalMode: "auto", fullAccess: true } as any);
135	  const events: any[] = [];
136	  let closed = false;
137	  const server = new SidecarServer({ app, mode: "auto", write: (line) => events.push(JSON.parse(line)), onShutdown: () => { closed = true; } });
138	  const observed: Observed = { steps: [], workspace: repo, modelRequests: 0, problems: [] };
139	  try {
140	    for (const [index, step] of recording.steps.entries()) {
141	      const label = stepLabel(step, index);
142	      const from = events.length;
143	      closed = false;
144	      if (step.send === undefined && step.raw === undefined) {
145	        if (index !== 0) throw new Error(`${label}: only the first step may be the connect step (no send, no raw)`);
146	        server.start();
147	      } else {
148	        if (index === 0) throw new Error("step 1 must be the connect step (no send, no raw)");
149	        const line = step.raw ?? JSON.stringify(step.send);
150	        let errors: string[];
151	        try {
152	          errors = validate(JSON.parse(line), COMMAND, schema);
153	        } catch {
154	          errors = ["not JSON"];
155	        }
156	        if (step.malformed === undefined && errors.length) observed.problems.push(`${label}: the line is not a valid command (${errors.join("; ")}); mark it "malformed" if that is intended`);
157	        if (step.malformed !== undefined && !errors.length) observed.problems.push(`${label}: marked malformed, but the line is a valid command`);
158	        await server.handleLine(line);
159	      }
160	      await server.idle();
161	      const emitted = events.slice(from);
162	      emitted.forEach((event, at) => {
163	        const errors = validate(event, EVENT, schema);
164	        if (errors.length) observed.problems.push(`${label}, event ${at + 1} (${String(event?.type)}): not valid against the schema: ${errors.join("; ")}`);
165	      });
166	      observed.steps.push({ events: emitted, closed });
167	    }
168	  } finally {
169	    await server.handleLine(JSON.stringify({ v: PROTOCOL_VERSION, type: "cancel" }));
170	    await server.idle();
171	    app.shutdown();
172	    observed.modelRequests = gw.requests.length;
173	    await gw.close();
174	    if (previousHome === undefined) delete process.env.HOME;
175	    else process.env.HOME = previousHome;
176	    fs.rmSync(repo, { recursive: true, force: true });
177	    fs.rmSync(home, { recursive: true, force: true });
178	  }
179	  return observed;
180	}
