182	const jsonType = (value: unknown): string => (value === null ? "null" : Array.isArray(value) ? "array" : typeof value);
183	const shown = (value: unknown): string => {
184	  const text = JSON.stringify(value);
185	  return text.length > 120 ? `${text.slice(0, 120)}…` : text;
186	};
