188	/** Where `actual` first departs from `expected` (see "Matching" above), or undefined. `ids` holds the captures so far. */
189	function mismatch(expected: unknown, actual: unknown, at: string, workspace: string, ids: Map<string, string>): string | undefined {
190	  if (typeof expected === "string") {
191	    const any = /^<any:(string|number|array)>$/.exec(expected);
192	    if (any) return jsonType(actual) === any[1] ? undefined : `${at}: expected any ${any[1]}, got ${shown(actual)}`;
193	    const id = /^<id:([\w-]+)>$/.exec(expected);
194	    if (id) {
195	      if (typeof actual !== "string" || !actual) return `${at}: expected a non-empty string for ${expected}, got ${shown(actual)}`;
196	      const bound = ids.get(id[1]);
197	      if (bound === undefined) ids.set(id[1], actual);
198	      else if (bound !== actual) return `${at}: expected ${expected} to be ${shown(bound)} again, got ${shown(actual)}`;
199	      return undefined;
200	    }
201	    const literal = expected.replaceAll("<workspace-name>", path.basename(workspace)).replaceAll("<workspace>", workspace);
202	    return literal === actual ? undefined : `${at}: expected ${shown(literal)}, got ${shown(actual)}`;
203	  }
204	  if (jsonType(expected) !== jsonType(actual)) return `${at}: expected ${shown(expected)}, got ${shown(actual)}`;
205	  if (Array.isArray(expected)) {
206	    const items = actual as unknown[];
207	    if (expected.length !== items.length) return `${at}: expected ${expected.length} items, got ${items.length}`;
208	    for (let i = 0; i < expected.length; i += 1) {
209	      const found = mismatch(expected[i], items[i], `${at}[${i}]`, workspace, ids);
210	      if (found) return found;
211	    }
212	    return undefined;
213	  }
214	  if (expected && typeof expected === "object") {
215	    const want = expected as Record<string, unknown>;
216	    const got = actual as Record<string, unknown>;
217	    for (const key of Object.keys(got)) if (!Object.hasOwn(want, key)) return `${at}: unexpected field ${key} = ${shown(got[key])}`;
218	    for (const key of Object.keys(want)) {
219	      if (!Object.hasOwn(got, key)) return `${at}: missing field ${key}`;
220	      const found = mismatch(want[key], got[key], `${at}.${key}`, workspace, ids);
221	      if (found) return found;
222	    }
223	    return undefined;
224	  }
225	  return expected === actual ? undefined : `${at}: expected ${shown(expected)}, got ${shown(actual)}`;
226	}
