10	export type Reply =
11	  /** `truncated`: the reply hits the output limit (finish_reason=length) partway through its tool calls' arguments. */
12	  | { kind: "tools"; calls: Array<{ name: string; args: unknown; id?: string }>; content?: string; delayMs?: number; truncated?: boolean }
13	  /** `chunks`: stream the text in these pieces, `gapMs` apart (the default sends it in one delta). `truncated`: finish_reason=length. */
14	  | { kind: "text"; content: string; delayMs?: number; chunks?: string[]; gapMs?: number; truncated?: boolean }
15	  | { kind: "http"; status: number; body?: string; delayMs?: number };
