17	export interface Gateway {
18	  url: string;
19	  requests: unknown[];
20	  /** Bodies of /tokenize requests (only with `options.tokenize`). */
21	  tokenizeRequests: any[];
22	  /** Number of GET /models requests served. */
23	  modelRequests: number;
24	  /** Authorization headers seen, per path kind. */
25	  authSeen: Array<{ path: string; authorization?: string }>;
26	  close(): Promise<void>;
27	}
