29	/** Optional gateway capabilities (homelab-ai contract shape): catalog entries, request counting, admission headers. */
30	export interface GatewayOptions {
31	  /** `data` entries for GET /models (default: [{ id: "m" }]). Called per request, so tests can change capacity. */
32	  models?: () => any[];
33	  /** Answer to POST /tokenize; absent: 404. */
34	  tokenize?: (body: any, n: number) => { status: number; body: unknown; delayMs?: number };
35	  /** Response headers for the n-th chat request (e.g. X-AIHost-* admission headers). */
36	  headers?: (n: number, body: any) => Record<string, string>;
37	}
