39	function sse(obj: unknown): string {
40	  return `data: ${JSON.stringify(obj)}\n\n`;
41	}
42	
43	/** A tool call's arguments as sent: whole, or cut off partway like a reply that hit the output limit. */
44	function wireArguments(args: unknown, truncated?: boolean): string {
45	  const json = JSON.stringify(args);
46	  return truncated ? json.slice(0, Math.max(1, Math.floor(json.length / 2))) : json;
47	}
48	
49	function finishReason(r: Extract<Reply, { kind: "tools" | "text" }>): string {
50	  return r.truncated ? "length" : r.kind === "tools" ? "tool_calls" : "stop";
51	}
52	
53	function streamBody(r: Extract<Reply, { kind: "tools" | "text" }>): string {
54	  let out = "";
55	  if (r.kind === "text") out += sse({ choices: [{ index: 0, delta: { content: r.content } }] });
56	  else {
57	    if (r.content) out += sse({ choices: [{ index: 0, delta: { content: r.content } }] });
58	    r.calls.forEach((c, i) => {
59	      out += sse({ choices: [{ index: 0, delta: { tool_calls: [{ index: i, id: c.id ?? `call_${i}_${Math.random().toString(36).slice(2, 7)}`, type: "function", function: { name: c.name, arguments: wireArguments(c.args, r.truncated) } }] } }] });
60	    });
61	  }
62	  out += sse({ choices: [{ index: 0, delta: {}, finish_reason: finishReason(r) }] });
63	  return out + "data: [DONE]\n\n";
64	}
