66	/** Deterministic OpenAI-compatible gateway. `script(n, body)` decides the reply to the n-th chat request (1-based). */
67	export async function startGateway(script: (n: number, body?: any) => Reply, options: GatewayOptions = {}): Promise<Gateway> {
68	  const requests: unknown[] = [];
69	  const tokenizeRequests: any[] = [];
70	  const authSeen: Array<{ path: string; authorization?: string }> = [];
71	  let modelRequests = 0;
72	  const sockets = new Set<Socket>();
73	  const server = http.createServer((req, res) => {
74	    authSeen.push({ path: req.url ?? "", authorization: req.headers.authorization });
75	    if (req.url?.endsWith("/models")) {
76	      modelRequests++;
77	      res.setHeader("content-type", "application/json");
78	      res.end(JSON.stringify({ data: options.models ? options.models() : [{ id: "m" }] }));
79	      return;
80	    }
81	    if (req.url?.endsWith("/tokenize")) {
82	      let raw = "";
83	      req.on("data", (c) => (raw += c));
84	      req.on("end", () => {
85	        let body: any = {};
86	        try { body = JSON.parse(raw); } catch {}
87	        tokenizeRequests.push(body);
88	        if (!options.tokenize) {
89	          res.statusCode = 404;
90	          res.end(JSON.stringify({ status: "not_found", message: "no tokenize" }));
91	          return;
92	        }
93	        const answer = options.tokenize(body, tokenizeRequests.length);
94	        const send = () => {
95	          if (res.writableEnded || res.destroyed) return;
96	          res.statusCode = answer.status;
97	          res.setHeader("content-type", "application/json");
98	          res.end(typeof answer.body === "string" ? answer.body : JSON.stringify(answer.body));
99	        };
100	        if (answer.delayMs) setTimeout(send, answer.delayMs); else send();
101	      });
102	      return;
103	    }
104	    let raw = "";
105	    req.on("data", (c) => (raw += c));
106	    req.on("end", () => {
107	      let body: any = {};
108	      try { body = JSON.parse(raw); } catch {}
109	      requests.push(body);
110	      const extraHeaders = options.headers ? options.headers(requests.length, body) : {};
111	      for (const [k, v] of Object.entries(extraHeaders)) res.setHeader(k, v);
112	      const r = script(requests.length, body);
113	      const respond = () => {
114	        if (res.writableEnded || res.destroyed) return;
115	        if (r.kind === "http") {
116	          res.statusCode = r.status;
117	          res.end(r.body ?? "{}");
118	        } else if (body.stream && r.kind === "text" && r.chunks?.length) {
119	          res.writeHead(200, { "content-type": "text/event-stream" });
120	          const pieces = [...r.chunks];
121	          const next = () => {
122	            if (res.writableEnded || res.destroyed) return;
123	            const piece = pieces.shift();
124	            if (piece === undefined) {
125	              res.end(sse({ choices: [{ index: 0, delta: {}, finish_reason: "stop" }] }) + "data: [DONE]\n\n");
126	              return;
127	            }
128	            res.write(sse({ choices: [{ index: 0, delta: { content: piece } }] }));
129	            setTimeout(next, r.gapMs ?? 50);
130	          };
131	          next();
132	        } else if (body.stream) {
133	          res.writeHead(200, { "content-type": "text/event-stream" });
134	          res.end(streamBody(r));
135	        } else {
136	          res.setHeader("content-type", "application/json");
137	          const message = r.kind === "text"
138	            ? { role: "assistant", content: r.content }
139	            : { role: "assistant", content: r.content ?? null, tool_calls: r.calls.map((c, i) => ({ id: c.id ?? `call_${i}`, type: "function", function: { name: c.name, arguments: wireArguments(c.args, r.truncated) } })) };
140	          res.end(JSON.stringify({ choices: [{ index: 0, message, finish_reason: r.truncated ? "length" : "stop" }] }));
141	        }
142	      };
143	      if (r.delayMs) setTimeout(respond, r.delayMs); else respond();
144	    });
145	  });
146	  server.on("connection", (s) => { sockets.add(s); s.on("close", () => sockets.delete(s)); });
147	  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", () => resolve()));
148	  const port = (server.address() as any).port;
149	  trackResource("gateway", `scripted gateway on port ${port} not closed`, () => server.listening, () => close());
150	  const close = async () => {
151	    for (const s of sockets) s.destroy();
152	    await new Promise<void>((resolve) => server.close(() => resolve()));
153	  };
154	  return {
155	    url: `http://127.0.0.1:${port}/v1`,
156	    requests,
157	    tokenizeRequests,
158	    get modelRequests() {
159	      return modelRequests;
160	    },
161	    authSeen,
162	    close,
163	  };
164	}
