202	/**
203	 * True once `pid` has terminated. A zombie counts as terminated: under a PID 1 that does not reap (some containers), a
204	 * killed process stays a zombie, and `kill(pid, 0)` still succeeds on it.
205	 */
206	export function processGone(pid: number): boolean {
207	  try {
208	    process.kill(pid, 0);
209	  } catch (error: unknown) {
210	    return (error as NodeJS.ErrnoException)?.code === "ESRCH";
211	  }
212	  // The process exists or is a zombie. `ps -p` exits 1 with no output once the pid is gone; if ps cannot run, the
213	  // process is not proven gone.
214	  const ps = spawnSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" });
215	  if (ps.error || (ps.status !== 0 && ps.status !== 1)) return false;
216	  const stat = ps.stdout.trim();
217	  return stat === "" || stat.startsWith("Z");
218	}
