220	export async function waitForEvent(events: any[], pred: (e: any) => boolean, timeoutMs = 10000): Promise<any> {
221	  try {
222	    await waitUntil(() => events.some(pred), timeoutMs);
223	  } catch {
224	    throw new Error(`timed out waiting for event; saw: ${events.map((e) => e.type).join(", ")}`);
225	  }
226	  return events.find(pred);
