229	/**
230	 * Pseudo-terminal scenarios measure timing (spinner frames, idle redraws, approval grace) and drive real processes;
231	 * run concurrently by the test runner they starve each other and keys arrive late. `ptyTest` holds a cross-process
232	 * lock (a directory under the system temp dir, taken over when its owner is gone) so they run one at a time.
233	 */
234	export async function acquirePtyLock(timeoutMs = 15 * 60_000): Promise<() => void> {
235	  const dir = path.join(os.tmpdir(), "nexus-pty-test.lock");
236	  const owner = path.join(dir, "pid");
237	  const deadline = Date.now() + timeoutMs;
238	  for (;;) {
239	    try {
240	      fs.mkdirSync(dir);
241	      fs.writeFileSync(owner, String(process.pid));
242	      return () => fs.rmSync(dir, { recursive: true, force: true });
243	    } catch (err: any) {
244	      if (err?.code !== "EEXIST") throw err;
245	      let pid = 0;
246	      try {
247	        pid = Number(fs.readFileSync(owner, "utf8"));
248	      } catch {}
249	      let alive = false;
250	      try {
251	        if (pid > 0) {
252	          process.kill(pid, 0);
253	          alive = true;
254	        }
255	      } catch {}
256	      // A lock without a live owner (crashed run, or an owner not yet written for a while) is taken over.
257	      if (!alive && (pid > 0 || Date.now() - fs.statSync(dir).mtimeMs > 5_000)) {
258	        fs.rmSync(dir, { recursive: true, force: true });
259	        continue;
260	      }
261	      if (Date.now() > deadline) throw new Error(`timed out waiting for the PTY test lock held by pid ${pid}`);
262	      await new Promise((r) => setTimeout(r, 200));
263	    }
264	  }
265	}
