881	  private resolveApproval(id: string, approved: boolean, always: boolean): void {
882	    const pending = this.pendingApproval;
883	    if (!pending || pending.id !== id) {
884	      this.emit({ type: "error", id, code: "NO_PENDING_APPROVAL", message: `No pending approval with id ${id}.` });
885	      return;
886	    }
887	    if (approved && always && pending.tool !== DELIBERATE_APPROVAL) {
888	      this.alwaysApprove = true;
889	      this.mode = "auto";
890	      this.app.getAgent().setApprovalMode("auto");
891	      this.emitSessionState();
892	    }
893	    // Only the operator's own Deny says "denied by you"; a cancelled turn or a shutdown settles the approval as false too.
894	    if (pending.tool !== DELIBERATE_APPROVAL) this.operatorDeclined = !approved;
895	    pending.settle(approved);
896	  }
