898	  private requestCheckpointChoice(
899	    turnId: string,
900	    signal: AbortSignal,
901	    message = "Sensitive content blocked the checkpoint. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 create a checkpoint anyway (may persist sensitive content), 4 cancel this turn, or 5 re-enter the instruction.",
902	    choices: readonly CheckpointChoice[] = ["read_only", "without_checkpoint", "allow_sensitive", "cancel", "other"],
903	  ): Promise<CheckpointChoice> {
904	    if (signal.aborted) return Promise.resolve("cancel");
905	    const id = `checkpoint-choice-${++this.approvalSeq}`;
906	    return new Promise((resolve) => {
907	      const settle = (choice: CheckpointChoice) => {
908	        signal.removeEventListener("abort", onAbort);
909	        this.pendingCheckpointChoice = undefined;
910	        resolve(choice);
911	      };
912	      const onAbort = () => settle("cancel");
913	      signal.addEventListener("abort", onAbort, { once: true });
914	      this.pendingCheckpointChoice = { id, choices, settle };
915	      this.emit({
916	        type: "checkpoint.choice.request",
917	        id,
918	        turn_id: turnId,
919	        message,
920	      });
921	    });
922	  }
