898	  private requestCheckpointChoice(
899	    turnId: string,
900	    signal: AbortSignal,
901	    message = "Sensitive content blocked the checkpoint. Choose 1 read-only, 2 continue without a rollback checkpoint, 3 create a checkpoint anyway (may persist sensitive content), 4 cancel this turn, or 5 re-enter the instruction.",
