1345	    if (typeof value !== "string") continue;
1346	    // Already cut to this limit by its producer: keep the producer's count of what was dropped. A model- or tool-supplied
1347	    // text that fakes the marker only spoofs that count; the skip is bounded, since the value is at most max + CAP_MARKER_ROOM.
1348	    if (value.length <= max + CAP_MARKER_ROOM && CAP_MARKER.test(value)) continue;
1349	    event[field] = capText(value, max);
1350	  }
1351	  if (event.type === "history") {
