1364	/** Every string in the value, made safe for the protocol: literal credential patterns removed, controls made visible. */
1365	function finishStrings<T>(value: T): T {
1366	  if (typeof value === "string") return visibleControls(redactSecretPatterns(value)) as T;
1367	  if (Array.isArray(value)) return value.map(finishStrings) as T;
1368	  if (value && typeof value === "object") {
1369	    return Object.fromEntries(Object.entries(value).map(([key, nested]) => [key, finishStrings(nested)])) as T;
1370	  }
1371	  return value;
