/**
 * Nexus sidecar protocol v1: newline-delimited JSON between the Ratatui client (parent) and the
 * Node agent sidecar (child). The sidecar projects agent state; it never asks the client to decide outcomes.
 */
import type { ProviderRecoveryRecord, TurnResult } from "./core/turn.js";
import { redactSecrets, safeTerminal } from "./ui.js";
import { persistableEndpoint, scrubUrls } from "./core/endpoint_identity.js";
import type { ApprovalReview } from "./approval_review.js";
import type { SlashSpec } from "./slash/catalog.js";
import type { EvidenceStatus, ReceiptSection } from "./evidence.js";
import type { Catalog } from "./model_catalog.js";

export const PROTOCOL_VERSION = 1;
/**
 * The inclusive range of protocol versions this sidecar can speak: `hello` announces it, `initialize` negotiates
 * inside it, and `parseCommand` accepts a message whose `v` lies in it. A version bump changes this pair (and
 * `PROTOCOL_VERSION`, the version the sidecar speaks by default) and nothing else in the negotiation.
 */
export const PROTOCOL_MIN = 1;
export const PROTOCOL_MAX = PROTOCOL_VERSION;
/** Largest protocol version number `initialize` accepts in a client's range (a bound on the field, not a version that exists). */
export const MAX_PROTOCOL_NUMBER = 65_535;
/** Longest `client.name` and `client.version` that `initialize` accepts. */
export const MAX_CLIENT_FIELD = 100;

/**
 * Stable features of this sidecar, announced in `hello` and `initialized`. Each name is the `type` of a command a
 * client may send beyond the minimal set every sidecar handles (`prompt.submit`, `cancel`, `approve`, `deny`,
 * `shutdown`), so a client checks `capabilities.includes(type)` before it sends that command. Sorted; a name is
 * never removed or given a new meaning within a protocol version.
 */
export const SIDECAR_CAPABILITIES = [
  /** `answer`: the operator's decision on a question a turn ended BLOCKED / NEEDS_INPUT with. */
  "answer",
  /** `checkpoint.choice`: the answer to a `checkpoint.choice.request` event. */
  "checkpoint.choice",
  /** `model.select`: switch model between turns; answered with `model.result`. */
  "model.select",
  /** `models.list`: providers and models; answered with `models.catalog`. */
  "models.list",
  /** `provider.connect`, with `provider.cancel` and `provider.local-cancel` for the same request; answered with `provider.auth` and `provider.result`. */
  "provider.connect",
  /** `provider.disconnect`: answered with `provider.result`. */
  "provider.disconnect",
  /** `receipt`: the evidence receipt of the last turn; answered with the `receipt` event. */
  "receipt",
  /** `slash`: run a command of the catalogue `hello` carries; answered with `slash.result`. */
  "slash",
  /** `steer`: guidance for the work in progress; answered with `steer.ack`. */
  "steer",
  /** `tool.detail`: the full record of one tool call; answered with the `tool.detail` event. */
  "tool.detail",
] as const;

/**
 * Experimental features this sidecar offers (none today). A new method sits here, refused with
 * `EXPERIMENTAL_DISABLED` unless the client sent `initialize` with `experimental: true`, until a conformance suite
 * has run against two real clients (docs/v1.3.0/PLAN.md, principle 8); then its name moves to SIDECAR_CAPABILITIES.
 */
export const EXPERIMENTAL_FEATURES: readonly string[] = [];
export const MAX_TEXT_FIELD = 8000;
/**
 * Longest clipboard text `/paste` puts into the composer, and the limit of the `slash.result` composer field. It keeps
 * the escaped `slash.result` line under the TUI's 1 MiB protocol line cap.
 */
export const MAX_PASTE = 100_000;
export const MAX_SUMMARY = 160;
export const MAX_SLASH_OUTPUT = 32_000;

/**
 * `UNSUPPORTED_PROTOCOL`: `initialize` named a version range that shares no version with the sidecar's.
 * `EXPERIMENTAL_DISABLED`: an experimental feature was used on a connection that did not enable it at `initialize`.
 */
export type ErrorCode = "BAD_REQUEST" | "BUSY" | "NO_PENDING_APPROVAL" | "NOT_FOUND" | "INTERNAL" | "NO_PROVIDER" | "UNSUPPORTED_PROTOCOL" | "EXPERIMENTAL_DISABLED";

/** Lines of a file diff shown in the transcript; the full diff is in the tool call's detail record. */
export const DIFF_PREVIEW_LINES = 40;
export const DIFF_PREVIEW_CHARS = 6000;

/**
 * What became of operator steering sent while work was running. `queued`: held for the next step boundary.
 * `applied`: given to the agent (at a step boundary, or as a follow-up turn). `deferred`: the turn was finishing; it
 * starts a follow-up turn. `cancelled`: the turn ended first; `text` is returned to the operator. `rejected`: nothing
 * it could steer (a command is running); `text` is returned. `duplicate`: this id was already received. `held`: the
 * steering negates a requirement and waits for the operator's decision; the outcome follows as `applied` or `cancelled`.
 */
export type SteerStatus = "held" | "queued" | "applied" | "deferred" | "cancelled" | "rejected" | "duplicate";

/** One entry of a resumed conversation: a message, a tool the agent called, or the last turn's outcome. */
export interface HistoryEntry {
  role: "user" | "assistant" | "steering" | "tool" | "outcome";
  text: string;
  tool?: string;
  heading?: string;
  turn?: TurnResult;
}

export interface ModelSummary {
  summary: string;
  notes?: string;
}

export type SidecarEvent =
  | {
      type: "hello";
      /** The version the sidecar speaks by default. */
      protocol: number;
      pid: number;
      commands: Array<Pick<SlashSpec, "name" | "usage" | "summary">>;
      /** The inclusive range of protocol versions this sidecar can speak. Absent from a sidecar older than capability negotiation: it speaks exactly `protocol`. */
      protocol_min?: number;
      protocol_max?: number;
      /** Stable features the sidecar supports (SIDECAR_CAPABILITIES), sorted. */
      capabilities?: string[];
      /** Experimental features the sidecar offers; each stays off until `initialize` asks with `experimental: true`. */
      experimental?: string[];
    }
  /**
   * Answer to `initialize`. `protocol`: the highest version both ranges contain. `experimental`: the experimental
   * features now enabled for this connection (empty unless the client asked for them).
   */
  | { type: "initialized"; id: string; protocol: number; capabilities: string[]; experimental: string[] }
  | {
      type: "session.state";
      workspace: string;
      workspace_name: string;
      model: string;
      mode: "auto" | "review" | "read-only";
      git: { branch: string; dirty: number } | null;
      busy: boolean;
      /** The id the session is saved under (shown so it can be resumed or referred to). */
      session?: string;
      /** The same facts the REPL /status reports (gate I-3). */
      read_only?: boolean;
      context_tokens?: number;
      context_limit?: number;
      endpoint_kind?: "local" | "cloud";
      posture?: {
        mode: "auto" | "review" | "read-only";
        sandbox: string;
        trusted: boolean;
      };
    }
  | { type: "assistant.delta"; turn_id: string; text: string }
  /** The provider's stream has sent nothing for `silent_secs` (`stalled`), or sent data again. */
  | { type: "stream.stall"; turn_id: string; stalled: boolean; silent_secs: number }
  /** What the running turn is doing; sent on every phase change, independent of model output. */
  | {
      type: "activity";
      turn_id: string;
      phase: string;
      step: number;
      segment: number;
      tool?: string;
      subject?: string;
      /** The turn's budget: total steps across segments, and the wall-clock limit in minutes (when continuation is on). */
      max_steps?: number;
      max_minutes?: number;
    }
  /** A file-edit tool changed a file: that operation's own diff (bounded preview; `evidence` opens the full one). */
  | {
      type: "file.diff";
      turn_id: string;
      call_id: string;
      evidence: string;
      path: string;
      kind: "added" | "modified" | "deleted";
      added: number;
      removed: number;
      preview: string;
      truncated: boolean;
      total_lines: number;
      /** Changed and context lines in the whole diff (what "N more lines" counts), and its hunks. */
      diff_lines: number;
      hunks: number;
      /** The complete diff on disk (redacted), kept for the session whatever the in-memory limits. */
      full_path?: string;
      note?: string;
    }
  | { type: "steer.ack"; id: string; status: SteerStatus; message: string; text?: string }
  | { type: "tool.start"; turn_id: string; call_id: string; tool: string; subject: string; evidence: string }
  | {
      type: "tool.end";
      turn_id: string;
      call_id: string;
      tool: string;
      success: boolean;
      summary: string;
      lines: number;
      evidence: string;
      /** Commands: the first lines of their output (stdout, then stderr), redacted, controls made visible. */
      preview?: string;
      exit_code?: number | null;
      duration_ms?: number;
      timed_out?: boolean;
      /** The operator declined the call at its approval prompt (never set for a policy refusal). The call did not run. */
      denied?: true;
    }
  | { type: "approval.request"; id: string; turn_id: string; tool: string; subject: string; preview: string; review: ApprovalReview }
  | { type: "checkpoint.choice.request"; id: string; turn_id: string; message: string }
  | { type: "turn.result"; turn_id: string; heading: string; line: string; turn: TurnResult; model_summary: ModelSummary | null; saved: boolean }
  | {
      type: "slash.result";
      id: string;
      command: string;
      success: boolean;
      output: string;
      /** "diff": colour unified-diff lines. */
      format?: "diff";
      /** Text for the client to put into the composer. */
      composer?: string;
      /** Text for the client to write to the terminal clipboard with OSC 52 (the client encodes it; at most OSC52_MAX_BYTES). */
      clipboard?: string;
      /** The command started a turn with this prompt; the turn's events follow under the same id. */
      prompt?: string;
    }
  /**
   * `key`: a later notice with the same key replaces this one on screen (a live status, not a log line).
   * `detail`: the raw cause, redacted, for the operator to inspect on request. Both are optional, so an older
   * client shows `text` as it always did.
   */
  | { type: "notice"; text: string; key?: string; detail?: string }
  /** A resumed session's recent conversation (user and assistant text only), oldest first; `total` counts all of it. */
  | { type: "history"; session: string; total: number; messages: HistoryEntry[] }
  | {
      type: "tool.detail";
      id: string;
      evidence: string;
      tool: string;
      subject: string;
      status: EvidenceStatus;
      args: string;
      output: string;
      duration_ms: number | null;
      /** Full unified diff of the change this call made, when it changed a file (at most MAX_DIFF_DETAIL chars). */
      diff?: string;
      /** Characters in the complete diff; more than `diff` holds when it was cut to the in-memory limit. */
      diff_chars?: number;
      /** The complete diff on disk. */
      diff_path?: string;
    }
  | { type: "receipt"; id: string; sections: ReceiptSection[] }
  | { type: "error"; id?: string; code: ErrorCode; message: string }
  /** Answer to models.list: providers (with connection source, never a credential), models, current and recent. */
  | ({ type: "models.catalog"; id: string } & Catalog)
  /** A sign-in needs the operator: open `url` (and type `user_code` for a device flow). */
  | { type: "provider.auth"; id: string; provider: string; url: string; user_code?: string; instructions: string }
  /** Outcome of provider.connect / provider.disconnect. */
  | { type: "provider.result"; id: string; provider: string; success: boolean; message: string }
