310	  const id = typeof msg.id === "string" && msg.id ? msg.id : undefined;
311	  const version = msg.v;
312	  if (typeof version !== "number" || !Number.isInteger(version) || version < PROTOCOL_MIN || version > PROTOCOL_MAX) {
